/* Card set: Disney Characters (generated from disney-full.csv by package_disney.py). */
CardSets.register({"id":"disney","name":"Disney Characters","code":"DISN","description":"Heroes, villains and sidekicks from Walt Disney Animation — from Snow White's first wish to Moana's voyage across the sea.","theme":{"primary":"#1b3a78","secondary":"#d9a441","artBackground":"#f8f9fa","artFit":"contain"},"pack":{"name":"Disney Pack","emblem":"🏰","skin":"disney"},"cards":[{"name":"Mickey Mouse","rarity":"chase","id":"mickey-mouse","subtitle":"Hero","details":"Disney's cheerful mouse icon, who debuted in Steamboat Willie in 1928 and leads with optimism, curiosity, and a can-do spirit.","image":"https://vignette.wikia.nocookie.net/disney/images/2/2e/Disney_Mickey_Mouse.png/revision/latest"},{"name":"Minnie Mouse","rarity":"chase","id":"minnie-mouse","subtitle":"Heroine","details":"Mickey's sweetheart since 1928, a graceful singer and dancer known for her polka-dot dress, bow, and warm, resourceful charm.","image":"https://vignette.wikia.nocookie.net/disney/images/6/67/Minnie_Mouse.png/revision/latest"},{"name":"Donald Duck","rarity":"chase","id":"donald-duck","subtitle":"Animal","details":"A short-tempered duck in a sailor suit, famous since 1934 for his explosive rants, stubborn pride, and surprising heart.","image":"https://vignette.wikia.nocookie.net/disney/images/a/ab/Donald_Duck_Disney_1.png/revision/latest"},{"name":"Goofy","rarity":"chase","id":"goofy","subtitle":"Animal","details":"Mickey's tall, clumsy best friend, a good-natured dog whose earnest attempts at everyday tasks usually end in gentle chaos.","image":"https://vignette.wikia.nocookie.net/disney/images/e/e5/Goofy.png/revision/latest"},{"name":"Pluto","rarity":"legendary","id":"pluto","subtitle":"Animal","details":"Mickey's loyal pet dog, who never speaks but says plenty through barks and devotion, especially when Chip and Dale tease him.","image":"https://vignette.wikia.nocookie.net/disney/images/1/13/Pluto_the_pup.png/revision/latest"},{"name":"Daisy Duck","rarity":"legendary","id":"daisy-duck","subtitle":"Animal","details":"Donald's confident girlfriend, a fashionable duck introduced in 1940 who is sweet one moment and fiercely exasperated the next.","image":"https://vignette.wikia.nocookie.net/disney/images/c/c9/Classic_Daisy_Duck.png/revision/latest"},{"name":"Pete","rarity":"epic","id":"pete","subtitle":"Villain","details":"Disney's longest-running villain, a burly cat who has menaced Mickey since 1925 as a steamboat captain, outlaw, and crook.","image":"https://vignette.wikia.nocookie.net/disney/images/7/7e/Pete.PNG/revision/latest"},{"name":"Scrooge McDuck","rarity":"epic","id":"scrooge-mcduck","subtitle":"Animal","details":"The richest duck in the world, a penny-pinching adventurer who swims through the coins in his Duckburg money bin.","image":"https://vignette.wikia.nocookie.net/disney/images/5/54/Scrooge_McDuck.png/revision/latest"},{"name":"Oswald the Lucky Rabbit","rarity":"epic","id":"oswald-the-lucky-rabbit","subtitle":"Animal","details":"Walt Disney's lucky rabbit from 1927, a mischievous star of early silent shorts created a year before Mickey Mouse.","image":"https://vignette.wikia.nocookie.net/disney/images/4/4b/Oswald_cartoon.png/revision/latest"},{"name":"Chip","rarity":"rare","id":"chip","subtitle":"Animal","details":"The smarter, more serious half of a chipmunk duo, with a small black nose and a talent for turning acorns into schemes.","image":"https://vignette.wikia.nocookie.net/disney/images/3/35/ChipAndDale.png/revision/latest"},{"name":"Dale","rarity":"rare","id":"dale","subtitle":"Animal","details":"The goofier half of the chipmunk duo, with a big red nose, buck teeth, and a laid-back knack for ruining Chip's plans.","image":"https://vignette.wikia.nocookie.net/disney/images/3/35/ChipAndDale.png/revision/latest"},{"name":"Huey, Dewey, and Louie","rarity":"rare","id":"huey-dewey-and-louie","subtitle":"Animal","details":"Donald's nephews in one card: Huey in red, Dewey in blue, and Louie in green - triplets whose mischief outsmarts their uncle.","image":"https://vignette.wikia.nocookie.net/disney/images/4/43/Huey_Dewey_Louie_artwork.jpg/revision/latest"},{"name":"Clarabelle Cow","rarity":"uncommon","id":"clarabelle-cow","subtitle":"Animal","details":"A tall cow and one of Mickey's oldest friends, dating to 1928; a cheerful gossip often paired with Horace Horsecollar.","image":"https://vignette.wikia.nocookie.net/disney/images/e/e1/Clarabelle_Cow_Pose.png/revision/latest"},{"name":"Horace Horsecollar","rarity":"common","id":"horace-horsecollar","subtitle":"Animal","details":"A horse from Disney's earliest shorts in 1929, an easygoing friend of Mickey's who is often paired with Clarabelle Cow.","image":"https://vignette.wikia.nocookie.net/disney/images/d/df/Horace_Horsecollar_ADHAM.png/revision/latest"},{"name":"Ludwig Von Drake","rarity":"uncommon","id":"ludwig-von-drake","subtitle":"Animal","details":"An eccentric duck professor and Donald's uncle, introduced in 1961 as a self-proclaimed expert on nearly every subject.","image":"https://vignette.wikia.nocookie.net/disney/images/5/5d/Ludwig_Promo_Art_2.png/revision/latest"},{"name":"Snow White","rarity":"chase","id":"snow-white","subtitle":"Princess","details":"The first Disney princess, from 1937: a kind, gentle maiden whose singing and optimism win over the dwarfs who shelter her.","image":"https://vignette.wikia.nocookie.net/disney/images/3/33/Profile_-_Snow_White.jpeg/revision/latest"},{"name":"Evil Queen","rarity":"legendary","id":"evil-queen","subtitle":"Queen","details":"Snow White's vain stepmother, who asks her Magic Mirror who is fairest and becomes an old hag to deliver a poisoned apple.","image":"https://vignette.wikia.nocookie.net/disney/images/8/89/Profile_-_The_Evil_Queen.jpeg/revision/latest"},{"name":"Grumpy","rarity":"rare","id":"grumpy","subtitle":"Sidekick","details":"The grumpiest of the Seven Dwarfs, who grumbles about Snow White's arrival but quietly becomes one of her protectors.","image":"https://vignette.wikia.nocookie.net/disney/images/e/ef/Profile_-_Grumpy.png/revision/latest"},{"name":"Dopey","rarity":"rare","id":"dopey","subtitle":"Sidekick","details":"The youngest, mute dwarf, whose oversized ears, clumsy sweetness, and diamond-mine antics make him a silent scene-stealer.","image":"https://vignette.wikia.nocookie.net/disney/images/f/f7/Profile_-_Dopey.png/revision/latest"},{"name":"Doc","rarity":"uncommon","id":"doc","subtitle":"Sidekick","details":"The bespectacled leader of the Seven Dwarfs, who mixes up his words when flustered but keeps the diamond mine running.","image":"https://vignette.wikia.nocookie.net/disney/images/1/17/Profile_-_Doc.png/revision/latest"},{"name":"Happy","rarity":"common","id":"happy","subtitle":"Sidekick","details":"The roly-poly dwarf with a perpetual grin, always ready with a laugh, a song, and an appetite at the cottage table.","image":"https://vignette.wikia.nocookie.net/disney/images/6/6b/Profile_-_Happy.png/revision/latest"},{"name":"Sleepy","rarity":"common","id":"sleepy","subtitle":"Sidekick","details":"The perpetually drowsy dwarf, whose heavy eyelids and slow drawl persist even through diamond mines and dances.","image":"https://vignette.wikia.nocookie.net/disney/images/8/84/Profile_-_Sleepy.png/revision/latest"},{"name":"Sneezy","rarity":"common","id":"sneezy","subtitle":"Sidekick","details":"The dwarf whose powerful hay-fever sneezes can blow his brothers across the room at the worst possible moment.","image":"https://vignette.wikia.nocookie.net/disney/images/7/7e/Profile_-_Sneezy.png/revision/latest"},{"name":"Bashful","rarity":"common","id":"bashful","subtitle":"Sidekick","details":"The shy, blushing dwarf who twists his beard and stammers whenever Snow White - or any attention - comes his way.","image":"https://vignette.wikia.nocookie.net/disney/images/5/52/Profile_-_Bashful.png/revision/latest"},{"name":"The Prince","rarity":"uncommon","id":"the-prince","subtitle":"Prince","details":"The prince who hears Snow White singing at a wishing well and later wakes her from the Queen's sleeping death with a kiss.","image":"https://vignette.wikia.nocookie.net/disney/images/4/43/Profile_-_The_Prince.png/revision/latest"},{"name":"Pinocchio","rarity":"legendary","id":"pinocchio","subtitle":"Hero","details":"A wooden puppet carved by Geppetto in 1940 who must prove himself brave, truthful, and unselfish to become a real boy.","image":"https://vignette.wikia.nocookie.net/disney/images/8/85/595152-pinocchio2_large.jpg/revision/latest"},{"name":"Jiminy Cricket","rarity":"legendary","id":"jiminy-cricket","subtitle":"Sidekick","details":"Pinocchio's appointed conscience, a dapper cricket who sings 'When You Wish Upon a Star' and tries to keep him out of trouble.","image":"https://vignette.wikia.nocookie.net/disney/images/f/f0/Profile_-_Jiminy_Cricket.jpeg/revision/latest"},{"name":"Geppetto","rarity":"rare","id":"geppetto","subtitle":"Hero","details":"The kind woodcarver who wishes his puppet Pinocchio to life, then braves the belly of Monstro the whale to bring him home.","image":"https://vignette.wikia.nocookie.net/disney/images/9/9e/Profile_-_Gepetto.jpeg/revision/latest"},{"name":"Blue Fairy","rarity":"rare","id":"blue-fairy","subtitle":"Fairy","details":"The gentle fairy who gives Pinocchio life and, after he proves his heart, grants Geppetto's wish by making him a real boy.","image":"https://vignette.wikia.nocookie.net/disney/images/4/45/Profile_-_Blue_Fairy.jpeg/revision/latest"},{"name":"Figaro","rarity":"common","id":"figaro","subtitle":"Animal","details":"Geppetto's tuxedo kitten, a jealous little scene-stealer who begrudges the new puppet his place by the workshop fire.","image":"https://vignette.wikia.nocookie.net/disney/images/c/cc/Profile_-_Figaro.jpg/revision/latest"},{"name":"Honest John","rarity":"uncommon","id":"honest-john","subtitle":"Villain","details":"A sly fox con artist, full name John Worthington Foulfellow, who lures Pinocchio toward Stromboli and Pleasure Island.","image":"https://vignette.wikia.nocookie.net/disney/images/5/55/Profile_-_Honest_John.jpeg/revision/latest"},{"name":"Stromboli","rarity":"common","id":"stromboli","subtitle":"Villain","details":"A burly, hot-tempered puppet master who locks Pinocchio in a cage and threatens to chop him into firewood.","image":"https://vignette.wikia.nocookie.net/disney/images/f/fd/Profile_-_Stromboli_.jpeg/revision/latest"},{"name":"Yen Sid","rarity":"uncommon","id":"yen-sid","subtitle":"Sorcerer","details":"The stern sorcerer of 'The Sorcerer's Apprentice,' whose name is 'Disney' spelled backward and whose hat Mickey borrows.","image":"https://vignette.wikia.nocookie.net/disney/images/8/8a/Yen_Sid.jpg/revision/latest"},{"name":"Chernabog","rarity":"uncommon","id":"chernabog","subtitle":"Villain","details":"The huge, winged demon of 'Night on Bald Mountain' in Fantasia (1940), who summons the dead until church bells drive him off.","image":"https://vignette.wikia.nocookie.net/disney/images/6/61/Profile_-_Chernabog.jpeg/revision/latest"},{"name":"Hyacinth Hippo","rarity":"common","id":"hyacinth-hippo","subtitle":"Animal","details":"The tutu-wearing hippo ballerina of Fantasia's 'Dance of the Hours,' who tiptoes through a comic ballet with an alligator.","image":"https://vignette.wikia.nocookie.net/disney/images/9/93/Fantasia-disneyscreencaps.com-12074.jpg/revision/latest"},{"name":"Dumbo","rarity":"legendary","id":"dumbo","subtitle":"Animal","details":"A big-eared baby elephant mocked as 'Dumbo' in 1941, until a magic feather and his friend Timothy help him discover he can fly.","image":"https://vignette.wikia.nocookie.net/disney/images/e/e2/Profile_-_Dumbo.jpg/revision/latest"},{"name":"Timothy Q. Mouse","rarity":"rare","id":"timothy-q-mouse","subtitle":"Animal","details":"A small circus mouse who befriends Dumbo, defends him from mockers, and coaxes the little elephant into believing he can fly.","image":"https://vignette.wikia.nocookie.net/disney/images/5/5a/Profile_-_Timothy_Q._Mouse.jpg/revision/latest"},{"name":"Mrs. Jumbo","rarity":"common","id":"mrs-jumbo","subtitle":"Animal","details":"Dumbo's devoted mother, who rocks her baby to 'Baby Mine' and is locked away for protecting him from a taunting boy.","image":"https://vignette.wikia.nocookie.net/disney/images/6/6f/Dumbo-disneyscreencaps_com-1870.jpg/revision/latest"},{"name":"Casey Junior","rarity":"common","id":"casey-junior","subtitle":"Animal","details":"The cheerful little circus locomotive who chugs 'I think I can' as he hauls the circus train over steep hills.","image":"https://vignette.wikia.nocookie.net/disney/images/1/19/Profile_-_Casey_Junior.png/revision/latest"},{"name":"Bambi","rarity":"legendary","id":"bambi","subtitle":"Animal","details":"A white-tailed deer prince born in the forest in 1942, who grows through friendship and loss to one day lead the herd.","image":"https://vignette.wikia.nocookie.net/disney/images/d/d5/32248bambi2_1.jpg/revision/latest"},{"name":"Thumper","rarity":"rare","id":"thumper","subtitle":"Animal","details":"Bambi's rabbit friend, famous for thumping his foot and repeating: if you can't say something nice, don't say anything at all.","image":"https://vignette.wikia.nocookie.net/disney/images/1/16/Profile_-_Thumper.png/revision/latest"},{"name":"Flower","rarity":"common","id":"flower","subtitle":"Animal","details":"A shy little skunk whom the young Bambi mistakenly names 'Flower' - a name the sweet, bashful animal happily keeps.","image":"https://vignette.wikia.nocookie.net/disney/images/2/25/Profile_-_Flower.png/revision/latest"},{"name":"Faline","rarity":"common","id":"faline","subtitle":"Animal","details":"Bambi's childhood playmate and later his mate, a gentle doe who teases the young prince when they meet in the meadow.","image":"https://vignette.wikia.nocookie.net/disney/images/e/e3/Faline.jpg/revision/latest"},{"name":"Great Prince of the Forest","rarity":"common","id":"great-prince-of-the-forest","subtitle":"Animal","details":"Bambi's father, the wise old stag of the forest, who guides his son after his mother's death and teaches him to survive.","image":"https://vignette.wikia.nocookie.net/disney/images/c/cb/Profile_-_Great_Prince_of_the_Forest.png/revision/latest"},{"name":"Jose Carioca","rarity":"uncommon","id":"jose-carioca","subtitle":"Animal","details":"A smooth Brazilian parrot from Saludos Amigos (1942), a samba-loving charmer who introduces Donald Duck to Rio's music.","image":"https://vignette.wikia.nocookie.net/disney/images/0/00/Jos%C3%A9_Carioca.png/revision/latest"},{"name":"Panchito Pistoles","rarity":"uncommon","id":"panchito-pistoles","subtitle":"Animal","details":"A Mexican rooster from The Three Caballeros (1944), whose pistols and serenades complete the trio with Donald and Jose.","image":"https://vignette.wikia.nocookie.net/disney/images/8/8e/Panchito_Pistoles.png/revision/latest"},{"name":"Willie the Giant","rarity":"common","id":"willie-the-giant","subtitle":"Villain","details":"The huge, dim-witted giant of 'Mickey and the Beanstalk' (1947), who kidnaps the Singing Harp and can shapeshift - badly.","image":"https://vignette.wikia.nocookie.net/disney/images/a/a6/Willie_the_Giant.jpg/revision/latest"},{"name":"Johnny Appleseed","rarity":"common","id":"johnny-appleseed","subtitle":"Hero","details":"The folk hero of Melody Time (1948), who wanders the frontier planting apple trees with a cooking-pot hat and a song.","image":"https://vignette.wikia.nocookie.net/disney/images/b/b9/Profile_-_Johnny_Appleseed.jpg/revision/latest"},{"name":"J. Thaddeus Toad","rarity":"uncommon","id":"j-thaddeus-toad","subtitle":"Animal","details":"A reckless English toad whose mania for motor cars in 1949 lands him in prison for a car theft he did not commit.","image":"https://vignette.wikia.nocookie.net/disney/images/a/ac/Profile_-_J._Thaddeus_Toad.jpg/revision/latest"},{"name":"Ichabod Crane","rarity":"uncommon","id":"ichabod-crane","subtitle":"Hero","details":"A lanky, superstitious schoolmaster in The Legend of Sleepy Hollow (1949), whose ride home meets the Headless Horseman.","image":"https://vignette.wikia.nocookie.net/disney/images/7/7f/Profile_-_Ichabob_Crane.jpg/revision/latest"},{"name":"Headless Horseman","rarity":"uncommon","id":"headless-horseman","subtitle":"Villain","details":"The galloping ghost of Sleepy Hollow, who hurls his flaming pumpkin head at Ichabod Crane on a bridge at night.","image":"https://vignette.wikia.nocookie.net/disney/images/5/5f/Iceraichabodmrtoad5626.jpg/revision/latest"},{"name":"Cinderella","rarity":"chase","id":"cinderella","subtitle":"Princess","details":"A kind, patient servant girl in 1950 whose Fairy Godmother, glass slippers, and a midnight deadline carry her to a royal ball.","image":"https://vignette.wikia.nocookie.net/disney/images/e/e5/Profile_-_Cinderella.jpeg/revision/latest"},{"name":"Fairy Godmother","rarity":"rare","id":"fairy-godmother","subtitle":"Fairy","details":"Cinderella's kind godmother, whose wand and a cheerful 'Bibbidi-Bobbidi-Boo' turn a pumpkin and mice into a coach and horses.","image":"https://vignette.wikia.nocookie.net/disney/images/d/d9/Profile_-_Fairy_Godmother.jpeg/revision/latest"},{"name":"Prince Charming","rarity":"common","id":"prince-charming","subtitle":"Prince","details":"The prince of Cinderella (1950) who dances with a mysterious guest at the ball and searches the kingdom with a glass slipper.","image":"https://vignette.wikia.nocookie.net/disney/images/e/ec/Profile_-_Prince_Charming.png/revision/latest"},{"name":"Lady Tremaine","rarity":"uncommon","id":"lady-tremaine","subtitle":"Villain","details":"Cinderella's cold, calculating stepmother, who locks her stepdaughter in the attic rather than let her try the slipper.","image":"https://vignette.wikia.nocookie.net/disney/images/4/42/Profile_-_Lady_Tremaine.jpeg/revision/latest"},{"name":"Anastasia Tremaine","rarity":"common","id":"anastasia-tremaine","subtitle":"Villain","details":"One of Cinderella's stepsisters, a clumsy, screechy flute player whose mother pushes her toward the Prince.","image":"https://vignette.wikia.nocookie.net/disney/images/f/f8/Profile_-_Anastasia_Tremaine.png/revision/latest"},{"name":"Drizella Tremaine","rarity":"common","id":"drizella-tremaine","subtitle":"Villain","details":"Cinderella's other stepsister, a tone-deaf singer whose vanity and cruelty mirror her mother Lady Tremaine's.","image":"https://vignette.wikia.nocookie.net/disney/images/e/e8/Cinderella-disneyscreencaps.com-4703.jpg/revision/latest"},{"name":"Jaq","rarity":"uncommon","id":"jaq","subtitle":"Animal","details":"The brave, skinny mouse who leads Cinderella's animal friends and risks everything to fetch the key to her locked door.","image":"https://vignette.wikia.nocookie.net/disney/images/d/d1/Profile_-_Jaq_and_Gus.jpeg/revision/latest"},{"name":"Gus","rarity":"uncommon","id":"gus","subtitle":"Animal","details":"A chubby, good-hearted mouse, full name Octavius, rescued from a trap by Cinderella and fiercely loyal to his friend Jaq.","image":"https://vignette.wikia.nocookie.net/disney/images/d/d1/Profile_-_Jaq_and_Gus.jpeg/revision/latest"},{"name":"Alice","rarity":"legendary","id":"alice","subtitle":"Heroine","details":"A curious girl who follows a White Rabbit down a rabbit hole in 1951 and wanders Wonderland asking very sensible questions.","image":"https://vignette.wikia.nocookie.net/disney/images/7/75/Profile_-_Alice.jpeg/revision/latest"},{"name":"Mad Hatter","rarity":"rare","id":"mad-hatter","subtitle":"Sidekick","details":"Wonderland's tea-party host, who celebrates unbirthdays, trades riddles without answers, and baffles Alice at every turn.","image":"https://vignette.wikia.nocookie.net/disney/images/1/19/Profile_-_Mad_Hatter.jpeg/revision/latest"},{"name":"Cheshire Cat","rarity":"rare","id":"cheshire-cat","subtitle":"Animal","details":"A grinning cat who appears and vanishes piece by piece, leaving his smile behind and Alice more confused than before.","image":"https://vignette.wikia.nocookie.net/disney/images/8/8e/DisneyCheshireCat.jpg/revision/latest"},{"name":"Queen of Hearts","rarity":"rare","id":"queen-of-hearts","subtitle":"Queen","details":"Wonderland's tyrannical queen, whose answer to every problem - from bad croquet to a stolen tart - is 'Off with their heads!'","image":"https://vignette.wikia.nocookie.net/disney/images/6/61/Profile_-_Queen_of_Hearts.jpeg/revision/latest"},{"name":"White Rabbit","rarity":"uncommon","id":"white-rabbit","subtitle":"Animal","details":"A frantic, waistcoated rabbit who is always late for a very important date and leads Alice deeper into Wonderland.","image":"https://vignette.wikia.nocookie.net/disney/images/0/0f/Profile_-_White_Rabbit.jpeg/revision/latest"},{"name":"Caterpillar","rarity":"common","id":"caterpillar","subtitle":"Animal","details":"A languid, hookah-smoking caterpillar who quizzes Alice with 'Who are you?' and advises her to keep her temper.","image":"https://vignette.wikia.nocookie.net/disney/images/4/4a/Caterpillar_AIW.jpg/revision/latest"},{"name":"Peter Pan","rarity":"legendary","id":"peter-pan","subtitle":"Hero","details":"The boy who wouldn't grow up, who flies the Darling children to Never Land in 1953 to fight pirates and live without rules.","image":"https://vignette.wikia.nocookie.net/disney/images/8/85/1085519-peter_pan_782_super.jpg/revision/latest"},{"name":"Tinker Bell","rarity":"legendary","id":"tinker-bell","subtitle":"Fairy","details":"Peter Pan's jealous fairy companion, whose pixie dust makes flight possible and whose light fades when belief falters.","image":"https://vignette.wikia.nocookie.net/disney/images/7/76/Profile_-_Tinker_Bell.jpeg/revision/latest"},{"name":"Captain Hook","rarity":"legendary","id":"captain-hook","subtitle":"Villain","details":"Never Land's flamboyant pirate captain, who lost a hand to Peter Pan and fears the crocodile that swallowed a ticking clock.","image":"https://vignette.wikia.nocookie.net/disney/images/0/0b/Profile_-_Captain_Hook.jpeg/revision/latest"},{"name":"Wendy Darling","rarity":"rare","id":"wendy-darling","subtitle":"Heroine","details":"The eldest Darling child, a storyteller who flies to Never Land and becomes a mother to Peter and the Lost Boys.","image":"https://vignette.wikia.nocookie.net/disney/images/5/53/Profile_-_Wendy_Darling.jpeg/revision/latest"},{"name":"John Darling","rarity":"common","id":"john-darling","subtitle":"Hero","details":"Wendy's serious middle brother, a top-hatted young strategist carried to Never Land in his nightshirt.","image":"https://vignette.wikia.nocookie.net/disney/images/9/92/John_Darling.jpg/revision/latest"},{"name":"Michael Darling","rarity":"common","id":"michael-darling","subtitle":"Hero","details":"The youngest Darling, a pajama-clad toddler who carries his teddy bear through every Never Land adventure.","image":"https://vignette.wikia.nocookie.net/disney/images/7/78/Profile_-_Michael_Darling.jpg/revision/latest"},{"name":"Mr. Smee","rarity":"uncommon","id":"mr-smee","subtitle":"Villain","details":"Captain Hook's bumbling, good-natured first mate, the only pirate in Never Land too soft-hearted to be truly villainous.","image":"https://vignette.wikia.nocookie.net/disney/images/6/6f/Mr._Smee_Profile.jpg/revision/latest"},{"name":"Tiger Lily","rarity":"uncommon","id":"tiger-lily","subtitle":"Princess","details":"A brave Never Land princess, daughter of the chief, who refuses to betray Peter Pan even while tied up by Captain Hook.","image":"https://vignette.wikia.nocookie.net/disney/images/a/a5/Profile_-_Tiger_Lily.jpeg/revision/latest"},{"name":"Lady","rarity":"epic","id":"lady","subtitle":"Animal","details":"A pampered cocker spaniel from 1955 whose sheltered life opens up when a streetwise stray shows her the town beyond her yard.","image":"https://vignette.wikia.nocookie.net/disney/images/0/06/Profile_-_Lady.jpeg/revision/latest"},{"name":"Tramp","rarity":"epic","id":"tramp","subtitle":"Animal","details":"A charming, footloose stray who shares a famous spaghetti dinner with Lady and protects her from the dogcatcher.","image":"https://vignette.wikia.nocookie.net/disney/images/f/fb/Profile_-_Tramp.jpeg/revision/latest"},{"name":"Jock","rarity":"uncommon","id":"jock","subtitle":"Animal","details":"A feisty Scottish terrier and Lady's loyal neighbor, who buries bones in the yard and distrusts the new baby at first.","image":"https://vignette.wikia.nocookie.net/disney/images/f/f7/Profile_-_Jock.jpeg/revision/latest"},{"name":"Trusty","rarity":"uncommon","id":"trusty","subtitle":"Animal","details":"An elderly bloodhound neighbor whose grandfather once tracked criminals, though his own sense of smell has long faded.","image":"https://vignette.wikia.nocookie.net/disney/images/8/82/Profile_-_Trusty_.jpeg/revision/latest"},{"name":"Si","rarity":"common","id":"si","subtitle":"Animal","details":"One of two sly Siamese cats who arrive in a basket and gleefully wreck Lady's home while framing her for the mess.","image":"https://vignette.wikia.nocookie.net/disney/images/7/7d/Profile_-_Si_and_Am.jpeg/revision/latest"},{"name":"Am","rarity":"common","id":"am","subtitle":"Animal","details":"The other Siamese cat of the devious duo, who joins Si in tormenting the goldfish and blaming Lady for everything.","image":"https://vignette.wikia.nocookie.net/disney/images/7/7d/Profile_-_Si_and_Am.jpeg/revision/latest"},{"name":"Peg","rarity":"common","id":"peg","subtitle":"Animal","details":"A knowing Pekingese songstress at the dog pound who sings 'He's a Tramp' and has clearly loved a few strays herself.","image":"https://cdn.rrauction.com/auction/443/3335284_1.jpg"},{"name":"Aurora","rarity":"epic","id":"aurora","subtitle":"Princess","details":"A princess cursed at her christening to prick her finger on a spinning wheel, raised in hiding as Briar Rose in 1959.","image":"https://vignette.wikia.nocookie.net/disney/images/2/2a/Profile_-_Aurora.jpeg/revision/latest"},{"name":"Maleficent","rarity":"legendary","id":"maleficent","subtitle":"Villain","details":"The Mistress of All Evil, an uninvited fairy who curses baby Aurora and later battles Prince Phillip as a fire-breathing dragon.","image":"https://vignette.wikia.nocookie.net/disney/images/0/05/Profile_-_Maleficent.jpeg/revision/latest"},{"name":"Prince Phillip","rarity":"rare","id":"prince-phillip","subtitle":"Prince","details":"The prince betrothed to Aurora as a child, who later fights through Maleficent's thorn forest armed with truth and virtue.","image":"https://vignette.wikia.nocookie.net/disney/images/8/86/Profile_-_Prince_Phillip.png/revision/latest"},{"name":"Flora","rarity":"uncommon","id":"flora","subtitle":"Fairy","details":"The red-clad leader of the three good fairies, who gives Aurora beauty and keeps her sisters' gift-giving on track.","image":"https://vignette.wikia.nocookie.net/disney/images/e/ea/Profile_-_Three_Good_Faries.png/revision/latest"},{"name":"Fauna","rarity":"common","id":"fauna","subtitle":"Fairy","details":"The green-clad middle fairy, a gentle baker whose gift to Aurora is song - and whose birthday cake needs propping up.","image":"https://vignette.wikia.nocookie.net/disney/images/e/ea/Profile_-_Three_Good_Faries.png/revision/latest"},{"name":"Merryweather","rarity":"uncommon","id":"merryweather","subtitle":"Fairy","details":"The blue-clad youngest fairy, whose softened gift turns Maleficent's death curse into a deep sleep instead.","image":"https://vignette.wikia.nocookie.net/disney/images/e/ea/Profile_-_Three_Good_Faries.png/revision/latest"},{"name":"Diablo","rarity":"common","id":"diablo","subtitle":"Animal","details":"Maleficent's pet raven and spy, who hunts the kingdom for the hidden Princess Aurora for sixteen long years.","image":"https://vignette.wikia.nocookie.net/disney/images/0/0c/Diablo.png/revision/latest"},{"name":"Cruella de Vil","rarity":"legendary","id":"cruella-de-vil","subtitle":"Villain","details":"A fur-obsessed heiress in 1961 who hires thieves to steal ninety-nine Dalmatian puppies for a spotted fur coat.","image":"https://vignette.wikia.nocookie.net/disney/images/9/92/Profile_-_Cruella.png/revision/latest"},{"name":"Pongo","rarity":"rare","id":"pongo","subtitle":"Animal","details":"A devoted Dalmatian father who uses the Twilight Bark, a chain of dogs across England, to rescue his stolen puppies.","image":"https://vignette.wikia.nocookie.net/disney/images/3/3c/Profile_-_Pongo.png/revision/latest"},{"name":"Perdita","rarity":"rare","id":"perdita","subtitle":"Animal","details":"The puppies' loving mother, who escaped Cruella's house with Pongo to search the snowy countryside for her litter.","image":"https://vignette.wikia.nocookie.net/disney/images/e/e2/Profile_-_Perdita.png/revision/latest"},{"name":"Roger Radcliffe","rarity":"uncommon","id":"roger-radcliffe","subtitle":"Hero","details":"Pongo's songwriter human, whose tune 'Cruella de Vil' turns his guest's name into London's catchiest insult.","image":"https://vignette.wikia.nocookie.net/disney/images/8/8e/Roger_Radcliffe_-_Profile.png/revision/latest"},{"name":"Anita Radcliffe","rarity":"uncommon","id":"anita-radcliffe","subtitle":"Heroine","details":"Roger's kind wife and Cruella's old schoolmate, who refuses to sell her Dalmatians' puppies at any price.","image":"https://vignette.wikia.nocookie.net/disney/images/c/cb/Anita_Radcliffe.png/revision/latest"},{"name":"Jasper Badun","rarity":"common","id":"jasper-badun","subtitle":"Villain","details":"One of the two bumbling Badun brothers hired by Cruella to steal and guard the Dalmatian puppies.","image":"https://vignette.wikia.nocookie.net/disney/images/4/41/101-dalmatians-disneyscreencaps.com-3006.jpg/revision/latest"},{"name":"Horace Badun","rarity":"common","id":"horace-badun","subtitle":"Villain","details":"The shorter, hungrier Badun brother, more interested in food and television than in Jasper and Cruella's scheme.","image":"https://vignette.wikia.nocookie.net/disney/images/4/41/101-dalmatians-disneyscreencaps.com-3006.jpg/revision/latest"},{"name":"Patch","rarity":"common","id":"patch","subtitle":"Animal","details":"The boldest of Pongo and Perdita's fifteen puppies, marked by a black patch over one eye and eager to be a hero.","image":"https://vignette.wikia.nocookie.net/disney/images/7/79/Profile_-_Patch.png/revision/latest"},{"name":"Merlin","rarity":"legendary","id":"merlin","subtitle":"Sorcerer","details":"A whimsical, absent-minded wizard who tutors the boy Wart with lessons learned as a fish, a squirrel, and a bird.","image":"https://vignette.wikia.nocookie.net/disney/images/e/ee/Merlin_Sword_in_the_Stone.jpeg/revision/latest"},{"name":"Arthur","rarity":"uncommon","id":"arthur","subtitle":"Hero","details":"A scrawny squire nicknamed Wart who pulls a sword from an anvil and discovers he is the rightful king of England.","image":"https://vignette.wikia.nocookie.net/disney/images/e/ec/Arthur_%28The_Sword_in_the_Stone%29.jpg/revision/latest"},{"name":"Archimedes","rarity":"common","id":"archimedes","subtitle":"Animal","details":"Merlin's highly educated, grumpy pet owl, who teaches young Arthur to fly and complains through every lesson.","image":"https://vignette.wikia.nocookie.net/disney/images/4/43/Archimedes.png/revision/latest"},{"name":"Madam Mim","rarity":"uncommon","id":"madam-mim","subtitle":"Villain","details":"The Marvelous Mad Madam Mim, a wicked witch who duels Merlin shape for shape in a famous wizards' contest.","image":"https://vignette.wikia.nocookie.net/disney/images/d/d6/Madam_Mim.jpg/revision/latest"},{"name":"Sir Kay","rarity":"common","id":"sir-kay","subtitle":"Hero","details":"Arthur's hulking foster brother, a knight-in-training who takes credit for the sword until Arthur pulls it himself.","image":"https://vignette.wikia.nocookie.net/disney/images/0/0a/Profile_-_Sir_Kay.png/revision/latest"},{"name":"Baloo","rarity":"legendary","id":"baloo","subtitle":"Animal","details":"A laid-back sloth bear who teaches Mowgli 'The Bare Necessities' and would happily float down rivers forever.","image":"https://vignette.wikia.nocookie.net/disney/images/3/31/Profile_-_Baloo.jpeg/revision/latest"},{"name":"Bagheera","rarity":"epic","id":"bagheera","subtitle":"Animal","details":"The wise black panther who found baby Mowgli and guides the man-cub back to the village, despite Baloo's detours.","image":"https://vignette.wikia.nocookie.net/disney/images/5/5c/Profile_-_Bagheera.jpeg/revision/latest"},{"name":"Shere Khan","rarity":"epic","id":"shere-khan","subtitle":"Villain","details":"A suave, fearsome tiger who hunts Mowgli through the jungle and fears only man's gun and man's fire.","image":"https://vignette.wikia.nocookie.net/disney/images/9/93/Profile_-_Shere_Khan.jpeg/revision/latest"},{"name":"Mowgli","rarity":"rare","id":"mowgli","subtitle":"Hero","details":"The man-cub raised by wolves in 1967, torn between Baloo's easy jungle life and the village where he belongs.","image":"https://vignette.wikia.nocookie.net/disney/images/3/3a/Profile_-_Mowgli.jpeg/revision/latest"},{"name":"Kaa","rarity":"uncommon","id":"kaa","subtitle":"Villain","details":"A hypnotic python whose sibilant 'Trust in Me' nearly makes a meal of Mowgli more than once.","image":"https://vignette.wikia.nocookie.net/disney/images/f/f8/Profile_-_Kaa.jpeg/revision/latest"},{"name":"King Louie","rarity":"uncommon","id":"king-louie","subtitle":"Animal","details":"An orangutan king of the ruins who wants Mowgli to teach him the secret of man's red fire so he can be like a man.","image":"https://vignette.wikia.nocookie.net/disney/images/b/b2/Profile_-_King_Louie.jpeg/revision/latest"},{"name":"Colonel Hathi","rarity":"common","id":"colonel-hathi","subtitle":"Animal","details":"The pompous elephant colonel who leads his herd on endless dawn patrols, trumpet fanfares and all.","image":"https://vignette.wikia.nocookie.net/disney/images/a/ad/Profile_-_Colonel_Hathi.jpeg/revision/latest"},{"name":"Shanti","rarity":"common","id":"shanti","subtitle":"Heroine","details":"The village girl whose song 'My Own Home' draws Mowgli out of the jungle at the end of his story.","image":"https://vignette.wikia.nocookie.net/disney/images/7/77/Profile_-_Shanti.jpeg/revision/latest"},{"name":"Duchess","rarity":"rare","id":"duchess","subtitle":"Animal","details":"An elegant white cat whose three kittens are stolen by a jealous butler; she crosses Paris to bring them home.","image":"https://vignette.wikia.nocookie.net/disney/images/e/eb/Profile_-_Duchess.jpeg/revision/latest"},{"name":"Thomas O'Malley","rarity":"rare","id":"thomas-omalley","subtitle":"Animal","details":"A smooth alley cat, full name Abraham de Lacy Giuseppe Casey Thomas O'Malley, who guides Duchess home to Paris.","image":"https://vignette.wikia.nocookie.net/disney/images/7/70/Profile_-_Thomas_O%27_Malley.jpeg/revision/latest"},{"name":"Marie","rarity":"rare","id":"marie","subtitle":"Animal","details":"Duchess's white kitten, a self-assured little singer who insists she is a lady and practices her scales and arpeggios.","image":"https://vignette.wikia.nocookie.net/disney/images/8/8f/Profile_-_Marie.jpeg/revision/latest"},{"name":"Berlioz","rarity":"common","id":"berlioz","subtitle":"Animal","details":"Duchess's black kitten, a piano-playing namesake of the composer, swept up in the butler Edgar's kidnapping plot.","image":"https://vignette.wikia.nocookie.net/disney/images/3/34/Berlioz.jpg/revision/latest"},{"name":"Toulouse","rarity":"common","id":"toulouse","subtitle":"Animal","details":"Duchess's orange kitten, an aspiring painter who idolizes tough alley cats and hisses at anything in his way.","image":"https://vignette.wikia.nocookie.net/disney/images/7/72/Toulouse.jpg/revision/latest"},{"name":"Edgar Balthazar","rarity":"common","id":"edgar-balthazar","subtitle":"Villain","details":"The greedy butler who drugs and abandons Duchess and her kittens in the countryside to steal their inheritance.","image":"https://vignette.wikia.nocookie.net/disney/images/8/89/Edgar_Balthazar.jpg/revision/latest"},{"name":"Roquefort","rarity":"common","id":"roquefort","subtitle":"Animal","details":"A tiny, brave mouse friend of the cats who rides a motorcycle sidecar into the country to find Duchess.","image":"https://vignette.wikia.nocookie.net/disney/images/1/16/Roquefort-Profile-Image.png.png/revision/latest"},{"name":"Robin Hood","rarity":"legendary","id":"robin-hood","subtitle":"Hero","details":"A heroic fox outlaw of 1973 who robs from the rich, gives to the poor, and outwits the Sheriff at every archery contest.","image":"https://vignette.wikia.nocookie.net/disney/images/4/42/Robin_Hood_Disney.jpg/revision/latest"},{"name":"Maid Marian","rarity":"epic","id":"maid-marian","subtitle":"Heroine","details":"Robin Hood's childhood sweetheart, a kind vixen living at Prince John's castle who never stopped loving the outlaw.","image":"https://vignette.wikia.nocookie.net/disney/images/b/b8/Maid_Marian.jpg/revision/latest"},{"name":"Little John","rarity":"rare","id":"little-john","subtitle":"Sidekick","details":"Robin's loyal bear partner, a master of disguises who helps rob Prince John's tax coach in the Sherwood Forest.","image":"https://vignette.wikia.nocookie.net/disney/images/c/cc/Little_John.jpg/revision/latest"},{"name":"Prince John","rarity":"rare","id":"prince-john","subtitle":"Prince","details":"The cowardly, thumb-sucking lion prince who taxes Nottingham into poverty while his brother Richard is away.","image":"https://vignette.wikia.nocookie.net/disney/images/b/b1/Prince_John_Disney.jpg/revision/latest"},{"name":"Sheriff of Nottingham","rarity":"uncommon","id":"sheriff-of-nottingham","subtitle":"Villain","details":"Prince John's oily wolf enforcer, who collects taxes from church poor boxes and hunts Robin Hood without success.","image":"https://vignette.wikia.nocookie.net/disney/images/a/a1/Profile_-_SheriffOfNottingham.png/revision/latest"},{"name":"Friar Tuck","rarity":"common","id":"friar-tuck","subtitle":"Sidekick","details":"Nottingham's kindly badger friar, who feeds the poor and is nearly hanged for striking the Sheriff in church.","image":"https://vignette.wikia.nocookie.net/disney/images/d/d5/Friar_Tuck_Disney.jpg/revision/latest"},{"name":"Sir Hiss","rarity":"uncommon","id":"sir-hiss","subtitle":"Villain","details":"Prince John's sniveling snake adviser, whose hypnotic past includes sending King Richard off on crusade.","image":"https://vignette.wikia.nocookie.net/disney/images/1/1d/Sir_Hiss_Disney.jpg/revision/latest"},{"name":"Skippy","rarity":"common","id":"skippy","subtitle":"Animal","details":"A young rabbit archer of Nottingham who idolizes Robin Hood and receives the outlaw's own hat and bow.","image":"https://vignette.wikia.nocookie.net/disney/images/3/3b/Profile_-_Skippy_Rabbit.png/revision/latest"},{"name":"Lady Kluck","rarity":"common","id":"lady-kluck","subtitle":"Animal","details":"Maid Marian's feisty hen lady-in-waiting, who fights guards with gusto when the archery tournament turns to chaos.","image":"https://vignette.wikia.nocookie.net/disney/images/6/6c/Lady_Cluck_Disney.jpg/revision/latest"},{"name":"Winnie the Pooh","rarity":"chase","id":"winnie-the-pooh","subtitle":"Animal","details":"A honey-obsessed bear of very little brain, who lives in the Hundred Acre Wood and thinks best with a full tummy.","image":"https://vignette.wikia.nocookie.net/disney/images/0/03/Profile_-_Winnie_the_Pooh.png/revision/latest"},{"name":"Tigger","rarity":"legendary","id":"tigger","subtitle":"Animal","details":"A bouncy, striped optimist whose favorite thing in the world is bouncing - especially on top of his friends.","image":"https://vignette.wikia.nocookie.net/disney/images/6/60/Profile_-_Tigger.png/revision/latest"},{"name":"Eeyore","rarity":"epic","id":"eeyore","subtitle":"Animal","details":"A gloomy old donkey who loses his tail, expects the worst, and still quietly joins every adventure in the Wood.","image":"https://vignette.wikia.nocookie.net/disney/images/1/1c/Profile_-_Eeyore.png/revision/latest"},{"name":"Piglet","rarity":"epic","id":"piglet","subtitle":"Animal","details":"Pooh's very small, timid best friend, who proves a Very Small Animal can be brave when his friends need him.","image":"https://vignette.wikia.nocookie.net/disney/images/5/5d/Profile_-_Piglet.png/revision/latest"},{"name":"Christopher Robin","rarity":"rare","id":"christopher-robin","subtitle":"Hero","details":"The boy whose stuffed animals fill the Hundred Acre Wood, and to whom Pooh promises to wait, wherever he goes.","image":"https://vignette.wikia.nocookie.net/disney/images/d/d5/Christopher_Robin_Pooh.jpg/revision/latest"},{"name":"Rabbit","rarity":"uncommon","id":"rabbit","subtitle":"Animal","details":"The Wood's fussy gardener and reluctant organizer, whose signs, plans, and carrot patch are always being trampled.","image":"https://vignette.wikia.nocookie.net/disney/images/d/da/Profile_-_Rabbit.png/revision/latest"},{"name":"Owl","rarity":"uncommon","id":"owl","subtitle":"Animal","details":"The Wood's long-winded storyteller, whose wise-sounding advice and endless family anecdotes solve very little.","image":"https://vignette.wikia.nocookie.net/disney/images/e/e4/Profile_-_Owl.jpeg/revision/latest"},{"name":"Kanga","rarity":"uncommon","id":"kanga","subtitle":"Animal","details":"The gentle mother of the Hundred Acre Wood, who offers warm Baths and spoonfuls of medicine to everyone she meets.","image":"https://vignette.wikia.nocookie.net/disney/images/c/c1/Profile_-_Kanga.png/revision/latest"},{"name":"Roo","rarity":"uncommon","id":"roo","subtitle":"Animal","details":"Kanga's pocket-sized joey, an eager little adventurer who wants to do everything Tigger does, only smaller.","image":"https://vignette.wikia.nocookie.net/disney/images/e/e6/Profile_-_Roo.png/revision/latest"},{"name":"Gopher","rarity":"common","id":"gopher","subtitle":"Animal","details":"A hard-hatted tunneler of the Wood who is 'not in the book' and keeps expanding his grand underground home.","image":"https://vignette.wikia.nocookie.net/disney/images/8/8a/Profile_-_Gopher.png/revision/latest"},{"name":"Bernard","rarity":"rare","id":"bernard","subtitle":"Hero","details":"A timid, superstitious mouse janitor of the Rescue Aid Society who becomes an unlikely hero beside Miss Bianca.","image":"https://vignette.wikia.nocookie.net/disney/images/b/b4/Bernard.png/revision/latest"},{"name":"Bianca","rarity":"rare","id":"bianca","subtitle":"Heroine","details":"The elegant Hungarian delegate to the Rescue Aid Society, a white mouse who chooses Bernard as her co-agent.","image":"https://vignette.wikia.nocookie.net/disney/images/f/f6/Miss_Bianca.png/revision/latest"},{"name":"Madame Medusa","rarity":"uncommon","id":"madame-medusa","subtitle":"Villain","details":"A wild-haired pawnshop villain who kidnaps the orphan Penny to retrieve a pirate's diamond from a flooded cave.","image":"https://vignette.wikia.nocookie.net/disney/images/5/5d/Madame-Medusa_.png/revision/latest"},{"name":"Penny","rarity":"uncommon","id":"penny","subtitle":"Heroine","details":"The lonely orphan of The Rescuers (1977), kidnapped for her small size and rescued with her teddy bear Teddy in tow.","image":"https://vignette.wikia.nocookie.net/disney/images/d/d5/Penny_%28The_Rescuers%29.png/revision/latest"},{"name":"Orville","rarity":"common","id":"orville","subtitle":"Animal","details":"The Rescuers' albatross pilot, who offers Bernard and Bianca a bumpy transatlantic flight - sardine can included.","image":"https://vignette.wikia.nocookie.net/disney/images/8/8d/Orville.png/revision/latest"},{"name":"Cody","rarity":"common","id":"cody","subtitle":"Hero","details":"The brave Australian boy of The Rescuers Down Under (1990) who frees the golden eagle Marahute and is kidnapped for it.","image":"https://vignette.wikia.nocookie.net/disney/images/4/45/Cody.png/revision/latest"},{"name":"Percival C. McLeach","rarity":"uncommon","id":"percival-c-mcleach","subtitle":"Villain","details":"A ruthless Outback poacher who traps the rare eagle Marahute and imprisons Cody in his armored half-track.","image":"https://vignette.wikia.nocookie.net/disney/images/9/97/Percival-McLeach.png/revision/latest"},{"name":"Marahute","rarity":"common","id":"marahute","subtitle":"Animal","details":"The great golden eagle of the Outback, whose stolen eggs make her the target of the poacher McLeach.","image":"https://vignette.wikia.nocookie.net/disney/images/8/87/Rescuers-down-under-disneyscreencaps_com-847.jpg/revision/latest"},{"name":"Tod","rarity":"uncommon","id":"tod","subtitle":"Animal","details":"A young red fox whose childhood friendship with a hound dog is tested by the roles nature and hunters assign them.","image":"https://vignette.wikia.nocookie.net/disney/images/c/c3/Profile_-_Tod.png/revision/latest"},{"name":"Copper","rarity":"uncommon","id":"copper","subtitle":"Animal","details":"A bloodhound puppy whose best friend is a fox - until Amos Slade's training turns friendship into instinct.","image":"https://vignette.wikia.nocookie.net/disney/images/c/cf/Profile_-_Copper.png/revision/latest"},{"name":"Big Mama","rarity":"common","id":"big-mama","subtitle":"Animal","details":"A motherly owl who sings Tod and Copper's story and tries to teach them that friendship can outlast nature.","image":"https://vignette.wikia.nocookie.net/disney/images/f/f8/Big-Mama-%28Fox_and_the_Hound%29.jpg/revision/latest"},{"name":"Widow Tweed","rarity":"common","id":"widow-tweed","subtitle":"Heroine","details":"The kind widow who raises the orphaned fox Tod and must set him free in a game preserve to save his life.","image":"https://vignette.wikia.nocookie.net/disney/images/6/62/Widow-Tweed-%28Fox_and_the_Hound%29.jpg/revision/latest"},{"name":"Amos Slade","rarity":"common","id":"amos-slade","subtitle":"Villain","details":"A stubborn hunter who trains Copper to track foxes and refuses to forgive Tod for his dog Chief's injury.","image":"https://vignette.wikia.nocookie.net/disney/images/c/cc/Fox-and-the-hound-disneyscreencaps.com-2010.jpg/revision/latest"},{"name":"Vixey","rarity":"common","id":"vixey","subtitle":"Animal","details":"A sweet vixen of the game preserve who shows the forest-raised-in-a-house Tod how to survive in the wild.","image":"https://vignette.wikia.nocookie.net/disney/images/3/34/Fox-and-the-hound-disneyscreencaps.com-7004.jpg/revision/latest"},{"name":"Taran","rarity":"common","id":"taran","subtitle":"Hero","details":"An assistant pig-keeper who dreams of heroism and must protect the oracular pig Hen Wen from the Horned King.","image":"https://vignette.wikia.nocookie.net/disney/images/9/91/Profile_-_Taran.jpg/revision/latest"},{"name":"Eilonwy","rarity":"common","id":"eilonwy","subtitle":"Princess","details":"A scullery-maid princess of Llyr with a floating bauble of light, sharper and braver than Taran first assumes.","image":"https://vignette.wikia.nocookie.net/disney/images/e/e3/Profile_-_Eilonwy.png/revision/latest"},{"name":"Gurgi","rarity":"common","id":"gurgi","subtitle":"Animal","details":"A small, hungry creature who speaks of himself in rhymes and offers Taran 'munchings and crunchings' and loyalty.","image":"https://vignette.wikia.nocookie.net/disney/images/d/d9/Gurgi.jpg/revision/latest"},{"name":"Horned King","rarity":"uncommon","id":"horned-king","subtitle":"Villain","details":"A skeletal tyrant who seeks the Black Cauldron to raise an army of the dead, the Cauldron-Born.","image":"https://vignette.wikia.nocookie.net/disney/images/2/29/Profile_-_Horned_King.jpg/revision/latest"},{"name":"Basil of Baker Street","rarity":"uncommon","id":"basil-of-baker-street","subtitle":"Hero","details":"A brilliant mouse detective of Baker Street who deduces, disguises, and violin-plays his way after Professor Ratigan.","image":"https://vignette.wikia.nocookie.net/disney/images/2/28/Basil_of_Baker_Street.png/revision/latest"},{"name":"Professor Ratigan","rarity":"uncommon","id":"professor-ratigan","subtitle":"Villain","details":"The world's greatest criminal mind - a rat who insists he is a mouse - plotting to overthrow the mouse queen.","image":"https://vignette.wikia.nocookie.net/disney/images/e/ec/Professor_Ratigan.png/revision/latest"},{"name":"David Q. Dawson","rarity":"common","id":"david-q-dawson","subtitle":"Sidekick","details":"Basil's loyal doctor companion, a mouse Watson who chronicles the Great Mouse Detective's cases with admiration.","image":"https://vignette.wikia.nocookie.net/disney/images/f/f0/David_Q._Dawson.png/revision/latest"},{"name":"Olivia Flaversham","rarity":"common","id":"olivia-flaversham","subtitle":"Heroine","details":"A brave young mouse whose toy-maker father is kidnapped by Ratigan, sending her to Basil for help.","image":"https://vignette.wikia.nocookie.net/disney/images/9/9e/Olivia_Flaversham.png/revision/latest"},{"name":"Oliver","rarity":"uncommon","id":"oliver","subtitle":"Animal","details":"An orphaned orange kitten lost in New York City who falls in with a gang of streetwise dogs and a kind girl.","image":"https://vignette.wikia.nocookie.net/disney/images/e/e6/Oliver.jpg/revision/latest"},{"name":"Dodger","rarity":"uncommon","id":"dodger","subtitle":"Animal","details":"The cool, shades-wearing leader of Fagin's dog gang, who teaches Oliver the street smarts of New York City.","image":"https://vignette.wikia.nocookie.net/disney/images/c/c2/Dodger.jpg/revision/latest"},{"name":"Fagin","rarity":"common","id":"fagin","subtitle":"Villain","details":"A kind-hearted but desperate pickpocket whose dog gang steals to pay off the menacing loan shark Sykes.","image":"https://vignette.wikia.nocookie.net/disney/images/2/2a/Fagin.png/revision/latest"},{"name":"Bill Sykes","rarity":"common","id":"bill-sykes","subtitle":"Villain","details":"A cold New York loan shark whose Dobermans and limousine make him the real danger behind Fagin's debts.","image":"https://vignette.wikia.nocookie.net/disney/images/a/ae/BillSykes.jpg/revision/latest"},{"name":"Jenny Foxworth","rarity":"common","id":"jenny-foxworth","subtitle":"Heroine","details":"A lonely, wealthy young pianist who adopts Oliver and is kidnapped by Sykes for ransom.","image":"https://vignette.wikia.nocookie.net/disney/images/5/59/JennyFoxworth.png/revision/latest"},{"name":"Rita","rarity":"common","id":"rita","subtitle":"Animal","details":"The streetwise Afghan hound of Fagin's gang, the cool-headed only female among Dodger's crew of strays.","image":"https://vignette.wikia.nocookie.net/disney/images/3/32/Rita.png/revision/latest"},{"name":"Georgette","rarity":"common","id":"georgette","subtitle":"Animal","details":"A pampered, prize-winning poodle of the Foxworth home who is scandalized by the stray dogs in her house.","image":"https://vignette.wikia.nocookie.net/disney/images/a/af/Georgette.jpg/revision/latest"},{"name":"Ariel","rarity":"chase","id":"ariel","subtitle":"Princess","details":"A curious mermaid princess of 1989 who trades her voice to the sea witch Ursula for three days as a human on land.","image":"https://vignette.wikia.nocookie.net/disney/images/8/8a/Profile_-_Ariel.jpg/revision/latest"},{"name":"Ursula","rarity":"legendary","id":"ursula","subtitle":"Villain","details":"The sea witch of Atlantica, a cunning octopus-like villain who collects the souls of poor unfortunate merfolk.","image":"https://vignette.wikia.nocookie.net/disney/images/7/72/Profile_-_Ursula.jpeg/revision/latest"},{"name":"Sebastian","rarity":"epic","id":"sebastian","subtitle":"Sidekick","details":"A Jamaican-accented crab composer and King Triton's adviser, tasked with keeping an eye on Ariel - and failing.","image":"https://vignette.wikia.nocookie.net/disney/images/c/ca/Profile_-_Sebastian.jpeg/revision/latest"},{"name":"Prince Eric","rarity":"rare","id":"prince-eric","subtitle":"Prince","details":"The shipwrecked prince Ariel saves and falls for, who searches for the girl whose voice he cannot forget.","image":"https://vignette.wikia.nocookie.net/disney/images/f/f1/Profile_-_Prince_Eric.jpeg/revision/latest"},{"name":"Flounder","rarity":"uncommon","id":"flounder","subtitle":"Animal","details":"Ariel's loyal little fish friend, a nervous guppy who follows her into shipwrecks despite his better judgment.","image":"https://vignette.wikia.nocookie.net/disney/images/6/60/Profile_-_Flounder.jpeg/revision/latest"},{"name":"Scuttle","rarity":"uncommon","id":"scuttle","subtitle":"Animal","details":"A self-appointed expert seagull who misidentifies human treasures - a fork is a 'dinglehopper' for combing hair.","image":"https://vignette.wikia.nocookie.net/disney/images/f/fe/Profile_-_Scuttle.png/revision/latest"},{"name":"King Triton","rarity":"uncommon","id":"king-triton","subtitle":"King","details":"Atlantica's stern, trident-wielding king, whose fear of humans softens when he sees how much Ariel loves Eric.","image":"https://vignette.wikia.nocookie.net/disney/images/d/df/Profile_-_King_Triton.jpeg/revision/latest"},{"name":"Grimsby","rarity":"common","id":"grimsby","subtitle":"Sidekick","details":"Prince Eric's prim valet and confidant, seasick at sea and gently scheming to see his prince happily married.","image":"https://vignette.wikia.nocookie.net/disney/images/d/df/Profile_-_Grismby.jpg/revision/latest"},{"name":"Max","rarity":"common","id":"max","subtitle":"Animal","details":"Prince Eric's shaggy, expressive sheepdog, the only one aboard who sees through Ursula's human disguise at once.","image":"https://vignette.wikia.nocookie.net/disney/images/6/63/Little-Mermaid-Screencap-the-little-mermaid-1869712-720-480.jpg/revision/latest"},{"name":"Belle","rarity":"legendary","id":"belle","subtitle":"Heroine","details":"A book-loving villager of 1991 who offers her own freedom for her father's and teaches a cursed prince to love.","image":"https://vignette.wikia.nocookie.net/disney/images/1/1b/Profile_-_Belle.jpeg/revision/latest"},{"name":"Beast","rarity":"legendary","id":"beast","subtitle":"Prince","details":"A prince cursed into a beast until he can love and earn love in return before the last rose petal falls.","image":"https://vignette.wikia.nocookie.net/disney/images/8/84/Profile_-_Beast.jpeg/revision/latest"},{"name":"Gaston","rarity":"epic","id":"gaston","subtitle":"Villain","details":"The village's vain, brawny hunter whose proposal Belle refuses and whose ego turns a mob against the Beast.","image":"https://vignette.wikia.nocookie.net/disney/images/d/d4/Profile_-_Gaston.jpeg/revision/latest"},{"name":"Lumiere","rarity":"rare","id":"lumiere","subtitle":"Sidekick","details":"The Beast's charming maitre d', transformed into a candelabra, who stages the show-stopping 'Be Our Guest.'","image":"https://vignette.wikia.nocookie.net/disney/images/f/f5/Profile_-_Lumiere.jpeg/revision/latest"},{"name":"Cogsworth","rarity":"rare","id":"cogsworth","subtitle":"Sidekick","details":"The Beast's tightly wound majordomo, transformed into a mantel clock, forever bickering with Lumiere.","image":"https://vignette.wikia.nocookie.net/disney/images/b/bd/Profile_-_Cogsworth.png/revision/latest"},{"name":"Mrs. Potts","rarity":"rare","id":"mrs-potts","subtitle":"Sidekick","details":"The castle's warm housekeeper, transformed into a teapot, who sings the title ballad as Belle and Beast dance.","image":"https://vignette.wikia.nocookie.net/disney/images/7/76/Profile_-_Mrs._Potts.jpeg/revision/latest"},{"name":"Chip Potts","rarity":"uncommon","id":"chip-potts","subtitle":"Sidekick","details":"Mrs. Potts's son, a chipped teacup who stows away in Belle's bag hoping to see the world beyond the castle.","image":"https://vignette.wikia.nocookie.net/disney/images/a/ac/Profile_-_Chip.png/revision/latest"},{"name":"LeFou","rarity":"common","id":"lefou","subtitle":"Villain","details":"Gaston's dim, devoted sidekick, whose name is French for 'the fool' and who sings his boss's praises in the tavern.","image":"https://vignette.wikia.nocookie.net/disney/images/c/c8/Profile_-_LeFou.jpeg/revision/latest"},{"name":"Maurice","rarity":"common","id":"maurice","subtitle":"Hero","details":"Belle's eccentric inventor father, mocked by the village and imprisoned by the Beast for picking a single rose.","image":"https://vignette.wikia.nocookie.net/disney/images/a/a0/Maurice_BATB.jpg/revision/latest"},{"name":"Aladdin","rarity":"legendary","id":"aladdin","subtitle":"Hero","details":"A kind-hearted Agrabah street rat of 1992 whose magic lamp and three wishes carry him from thief to prince.","image":"https://vignette.wikia.nocookie.net/disney/images/b/bb/Profile_-_Aladdin.png/revision/latest"},{"name":"Genie","rarity":"legendary","id":"genie","subtitle":"Sidekick","details":"The all-powerful, fast-talking spirit of the lamp, bound to grant wishes while longing for the one thing he can't give himself.","image":"https://vignette.wikia.nocookie.net/disney/images/9/92/Profile_-_Genie.jpeg/revision/latest"},{"name":"Jasmine","rarity":"epic","id":"jasmine","subtitle":"Princess","details":"Agrabah's determined princess, who flees the palace in disguise rather than marry a prince she does not love.","image":"https://vignette.wikia.nocookie.net/disney/images/c/cd/Profile_-_Jasmine.jpeg/revision/latest"},{"name":"Jafar","rarity":"epic","id":"jafar","subtitle":"Villain","details":"The Sultan's sinister vizier, whose cobra staff, parrot Iago, and hunger for the lamp drive him to seize the throne.","image":"https://vignette.wikia.nocookie.net/disney/images/6/60/Profile_-_Jafar.jpeg/revision/latest"},{"name":"Abu","rarity":"rare","id":"abu","subtitle":"Animal","details":"Aladdin's kleptomaniac monkey partner, whose greed for treasure nearly traps them in the collapsing Cave of Wonders.","image":"https://vignette.wikia.nocookie.net/disney/images/3/3f/Profile_-_Abu.png/revision/latest"},{"name":"Iago","rarity":"rare","id":"iago","subtitle":"Animal","details":"Jafar's loud, wisecracking parrot, forever fed crackers by the Sultan and scheming for a throne of his own snacks.","image":"https://vignette.wikia.nocookie.net/disney/images/6/69/Profile_-_Iago.jpeg/revision/latest"},{"name":"Sultan","rarity":"uncommon","id":"sultan","subtitle":"King","details":"Agrabah's jolly, toy-loving ruler, more grandfather than king, who wants his daughter Jasmine safely married.","image":"https://vignette.wikia.nocookie.net/disney/images/3/31/Profile_-_The_Sultan.jpeg/revision/latest"},{"name":"Rajah","rarity":"common","id":"rajah","subtitle":"Animal","details":"Jasmine's loyal pet tiger, who guards the princess, chases off suitors, and shreds more than one royal trouser.","image":"https://vignette.wikia.nocookie.net/disney/images/0/02/Profile_-_Rajah.jpeg/revision/latest"},{"name":"Simba","rarity":"chase","id":"simba","subtitle":"King","details":"A lion cub prince of 1994 who flees Pride Rock believing he caused his father's death, then returns to claim his place.","image":"https://vignette.wikia.nocookie.net/disney/images/3/37/Profile_-_Simba.jpeg/revision/latest"},{"name":"Scar","rarity":"legendary","id":"scar","subtitle":"Villain","details":"Mufasa's bitter younger brother, whose 'Be Prepared' alliance with the hyenas brings ruin to the Pride Lands.","image":"https://vignette.wikia.nocookie.net/disney/images/6/66/Profile_-_Scar.jpeg/revision/latest"},{"name":"Mufasa","rarity":"legendary","id":"mufasa","subtitle":"King","details":"The wise King of Pride Rock, who teaches Simba the Circle of Life and watches over him from the stars.","image":"https://vignette.wikia.nocookie.net/disney/images/5/5e/Mufasa_Lion_King_.jpg/revision/latest"},{"name":"Nala","rarity":"epic","id":"nala","subtitle":"Queen","details":"Simba's childhood friend and later queen, who leaves the ruined Pride Lands seeking help and finds the lost king.","image":"https://vignette.wikia.nocookie.net/disney/images/5/55/Profile_-_Nala.jpeg/revision/latest"},{"name":"Timon","rarity":"epic","id":"timon","subtitle":"Sidekick","details":"A wisecracking meerkat who, with Pumbaa, teaches the exiled Simba their carefree philosophy: hakuna matata.","image":"https://vignette.wikia.nocookie.net/disney/images/4/45/Profile_-_Timon.jpeg/revision/latest"},{"name":"Pumbaa","rarity":"epic","id":"pumbaa","subtitle":"Sidekick","details":"A sweet, flatulent warthog, the first of his kind to befriend a lion, and Timon's partner in hakuna matata.","image":"https://vignette.wikia.nocookie.net/disney/images/e/e6/Profile_-_Pumbaa.jpeg/revision/latest"},{"name":"Rafiki","rarity":"epic","id":"rafiki","subtitle":"Sidekick","details":"The Pride Lands' eccentric mandrill shaman, who presents newborn cubs from Pride Rock and knocks sense into Simba.","image":"https://vignette.wikia.nocookie.net/disney/images/3/32/Profile_-_Rafiki.jpeg/revision/latest"},{"name":"Zazu","rarity":"rare","id":"zazu","subtitle":"Sidekick","details":"Mufasa's punctilious hornbill majordomo, who delivers the morning report and is forever being sat on by cubs.","image":"https://vignette.wikia.nocookie.net/disney/images/9/95/Profile_-_Zazu.jpeg/revision/latest"},{"name":"Sarabi","rarity":"common","id":"sarabi","subtitle":"Queen","details":"Simba's mother and Mufasa's queen, who holds the lionesses together through Scar's long, hungry reign.","image":"https://vignette.wikia.nocookie.net/disney/images/2/2f/Sarabi.jpg/revision/latest"},{"name":"Shenzi","rarity":"common","id":"shenzi","subtitle":"Villain","details":"The sharp-tongued leader of the hyena trio who serve Scar, always hungry and first to question his promises.","image":"https://vignette.wikia.nocookie.net/disney/images/b/b3/Lionking-disneyscreencaps.com-2439.jpg/revision/latest"},{"name":"Pocahontas","rarity":"rare","id":"pocahontas","subtitle":"Princess","details":"A free-spirited Powhatan chief's daughter of 1995 who follows the wind and paints with all the colors of it.","image":"https://vignette.wikia.nocookie.net/disney/images/7/7b/Profile_-_Pocahontas.jpeg/revision/latest"},{"name":"John Smith","rarity":"uncommon","id":"john-smith","subtitle":"Hero","details":"An English explorer who sails to Virginia for gold and adventure and learns another way of living from Pocahontas.","image":"https://vignette.wikia.nocookie.net/disney/images/5/5e/Profile_-_John_Smith.png/revision/latest"},{"name":"Meeko","rarity":"uncommon","id":"meeko","subtitle":"Animal","details":"A mischievous raccoon with an endless appetite, especially for John Smith's biscuits and Flit's patience.","image":"https://vignette.wikia.nocookie.net/disney/images/f/ff/Meeko_%28Pocahontas%29.jpg/revision/latest"},{"name":"Flit","rarity":"common","id":"flit","subtitle":"Animal","details":"A proud little hummingbird, Pocahontas's loyal friend, deeply suspicious of strangers and of Meeko's antics.","image":"https://vignette.wikia.nocookie.net/disney/images/b/bc/Flit.jpg/revision/latest"},{"name":"Governor Ratcliffe","rarity":"uncommon","id":"governor-ratcliffe","subtitle":"Villain","details":"The greedy governor of the Virginia expedition, digging for gold that isn't there and blaming everyone else.","image":"https://vignette.wikia.nocookie.net/disney/images/7/79/Profile_-_Governor_Ratcliffe.png/revision/latest"},{"name":"Grandmother Willow","rarity":"uncommon","id":"grandmother-willow","subtitle":"Spirit","details":"A wise, ancient talking willow tree who counsels Pocahontas to listen with her heart and find her path.","image":"https://vignette.wikia.nocookie.net/disney/images/d/dc/Pocahontas-disneyscreencaps.com-1801.jpg/revision/latest"},{"name":"Nakoma","rarity":"common","id":"nakoma","subtitle":"Sidekick","details":"Pocahontas's practical best friend, engaged to Kocoum, who worries her friend's risks will bring trouble home.","image":"https://vignette.wikia.nocookie.net/disney/images/f/fe/Nakoma_1.jpg/revision/latest"},{"name":"Quasimodo","rarity":"rare","id":"quasimodo","subtitle":"Hero","details":"Notre Dame's gentle, deformed bell-ringer of 1996, hidden from Paris by Frollo and longing to live out there.","image":"https://vignette.wikia.nocookie.net/disney/images/7/7f/Quasimodo.jpeg/revision/latest"},{"name":"Esmeralda","rarity":"rare","id":"esmeralda","subtitle":"Heroine","details":"A fearless Romani dancer who defies Frollo, befriends Quasimodo, and pleads for justice in the cathedral square.","image":"https://vignette.wikia.nocookie.net/disney/images/e/e4/Profile_-_Esmeralda.png/revision/latest"},{"name":"Claude Frollo","rarity":"uncommon","id":"claude-frollo","subtitle":"Villain","details":"Paris's self-righteous Minister of Justice, whose obsession with Esmeralda and hatred consume him entirely.","image":"https://vignette.wikia.nocookie.net/disney/images/6/64/Judge_Frollo.jpg/revision/latest"},{"name":"Phoebus","rarity":"uncommon","id":"phoebus","subtitle":"Hero","details":"The kind captain of the guard who defies Frollo's orders and falls for the courageous Esmeralda.","image":"https://vignette.wikia.nocookie.net/disney/images/4/4d/Phoebus_-_Profile.jpg/revision/latest"},{"name":"Clopin","rarity":"common","id":"clopin","subtitle":"Sidekick","details":"The Romani king and puppet-show narrator who tells Quasimodo's tale and leads the Court of Miracles.","image":"https://vignette.wikia.nocookie.net/disney/images/2/28/Profile_-_Clopin.jpeg/revision/latest"},{"name":"Hugo","rarity":"common","id":"hugo","subtitle":"Sidekick","details":"The rowdiest of Quasimodo's gargoyle friends, a stone comedian who urges the bell-ringer to seize the day.","image":"https://vignette.wikia.nocookie.net/disney/images/9/9b/Victor%2C_Hugo_and_Laverne.jpeg/revision/latest"},{"name":"Djali","rarity":"common","id":"djali","subtitle":"Animal","details":"Esmeralda's clever pet goat, who performs in her street dances and headbutts guards when the chase is on.","image":"https://vignette.wikia.nocookie.net/disney/images/1/12/Djali_HOND.jpg/revision/latest"},{"name":"Hercules","rarity":"rare","id":"hercules","subtitle":"Hero","details":"A god born with immense strength, raised mortal, who must become a true hero to reclaim his place on Olympus.","image":"https://vignette.wikia.nocookie.net/disney/images/7/70/Profile_-_Hercules.jpeg/revision/latest"},{"name":"Megara","rarity":"rare","id":"megara","subtitle":"Heroine","details":"A sharp-tongued cynic who sold her soul to Hades and swore off love - until a wonder boy named Hercules arrived.","image":"https://vignette.wikia.nocookie.net/disney/images/9/91/Profile_-_Megara.jpeg/revision/latest"},{"name":"Hades","rarity":"uncommon","id":"hades","subtitle":"Villain","details":"The fast-talking Lord of the Dead, whose hair flames blue when calm and red when his eighteen-year plan unravels.","image":"https://vignette.wikia.nocookie.net/disney/images/2/2c/Profile_-_Hades.jpeg/revision/latest"},{"name":"Philoctetes","rarity":"uncommon","id":"philoctetes","subtitle":"Sidekick","details":"A gruff satyr trainer of heroes, called Phil, whose dream student finally arrives in the hopeless young Hercules.","image":"https://vignette.wikia.nocookie.net/disney/images/7/7a/Profile_-_Philoctetes.jpeg/revision/latest"},{"name":"Pegasus","rarity":"uncommon","id":"pegasus","subtitle":"Animal","details":"Hercules's loyal winged horse, a gift from Zeus made of clouds, part steed, part jealous best friend.","image":"https://vignette.wikia.nocookie.net/disney/images/5/5c/Pegasus_Hercules.jpg/revision/latest"},{"name":"Pain","rarity":"common","id":"pain","subtitle":"Villain","details":"One of Hades's two bumbling demon henchmen, a stout imp who turns Hercules mortal with a stolen potion.","image":"https://vignette.wikia.nocookie.net/disney/images/7/75/Profile_-_Pain_and_Panic.jpg/revision/latest"},{"name":"Panic","rarity":"common","id":"panic","subtitle":"Villain","details":"The thin, anxious half of Hades's imp duo, forever fearing what happens when the boss finds out they failed.","image":"https://vignette.wikia.nocookie.net/disney/images/7/75/Profile_-_Pain_and_Panic.jpg/revision/latest"},{"name":"Zeus","rarity":"uncommon","id":"zeus","subtitle":"King","details":"The thunderous King of the Gods on Mount Olympus, who loses his infant son to Hades's plot and waits years for him.","image":"https://vignette.wikia.nocookie.net/disney/images/4/43/Zeus_Hercules_97.jpg/revision/latest"},{"name":"Mulan","rarity":"legendary","id":"mulan","subtitle":"Heroine","details":"A spirited young woman of 1998 who disguises herself as a man to take her injured father's place in the army.","image":"https://vignette.wikia.nocookie.net/disney/images/0/04/Profile_-_Mulan.jpeg/revision/latest"},{"name":"Mushu","rarity":"uncommon","id":"mushu","subtitle":"Sidekick","details":"A small, fast-talking dragon demoted to gong-ringer, sent to protect Mulan and desperate to restore his honor.","image":"https://vignette.wikia.nocookie.net/disney/images/1/17/Profile_-_Mushu.jpeg/revision/latest"},{"name":"Li Shang","rarity":"uncommon","id":"li-shang","subtitle":"Hero","details":"The disciplined captain who trains Mulan's unit, never guessing his best soldier is the woman he later admires.","image":"https://vignette.wikia.nocookie.net/disney/images/d/da/Profile_-_Shang.jpeg/revision/latest"},{"name":"Cri-Kee","rarity":"common","id":"cri-kee","subtitle":"Animal","details":"Mulan's 'lucky' cricket, a tiny companion carried in a cage whose luck is mostly a matter of opinion.","image":"https://vignette.wikia.nocookie.net/disney/images/f/f3/Profile_Cri-Kee.png/revision/latest"},{"name":"Shan Yu","rarity":"uncommon","id":"shan-yu","subtitle":"Villain","details":"The ruthless Hun leader with falcon eyes and a hawk on his arm, who brings war over the Great Wall to China.","image":"https://vignette.wikia.nocookie.net/disney/images/d/da/Profile_-_Shan_Yu.jpeg/revision/latest"},{"name":"Yao","rarity":"common","id":"yao","subtitle":"Sidekick","details":"The short, gruff, black-eyed brawler of Mulan's unit, quick to fight and quicker to defend his comrades.","image":"https://vignette.wikia.nocookie.net/disney/images/e/e3/Profile_-_Yao%2C_Ling%2C_Chien_Po.jpeg/revision/latest"},{"name":"Ling","rarity":"common","id":"ling","subtitle":"Sidekick","details":"The tall, wisecracking joker of Mulan's unit, always hungry and always ready with a line to lighten the march.","image":"https://vignette.wikia.nocookie.net/disney/images/e/e3/Profile_-_Yao%2C_Ling%2C_Chien_Po.jpeg/revision/latest"},{"name":"Chien-Po","rarity":"common","id":"chien-po","subtitle":"Sidekick","details":"The huge, gentle giant of Mulan's unit, whose calm strength and love of food balance Yao and Ling's chaos.","image":"https://vignette.wikia.nocookie.net/disney/images/e/e3/Profile_-_Yao%2C_Ling%2C_Chien_Po.jpeg/revision/latest"},{"name":"Tarzan","rarity":"rare","id":"tarzan","subtitle":"Hero","details":"A man raised by gorillas in the African jungle, torn between the family that raised him and the humans he resembles.","image":"https://vignette.wikia.nocookie.net/disney/images/2/2e/Profile_-_Tarzan.png/revision/latest"},{"name":"Jane Porter","rarity":"rare","id":"jane-porter","subtitle":"Heroine","details":"A bright English artist sketching jungle wildlife who meets a vine-swinging 'wild man' and teaches him her world.","image":"https://vignette.wikia.nocookie.net/disney/images/e/ef/Profile_-_Jane_Porter.png/revision/latest"},{"name":"Clayton","rarity":"common","id":"clayton","subtitle":"Villain","details":"The Porters' hired gun and guide, whose poaching ambitions turn him into the jungle's most dangerous hunter.","image":"https://vignette.wikia.nocookie.net/disney/images/e/e2/Clayton_profile_.jpg/revision/latest"},{"name":"Terk","rarity":"uncommon","id":"terk","subtitle":"Animal","details":"Tarzan's gorilla best friend, full name Terkina, a sarcastic prankster who leads the jungle's young apes.","image":"https://vignette.wikia.nocookie.net/disney/images/0/09/Terk.jpg/revision/latest"},{"name":"Tantor","rarity":"common","id":"tantor","subtitle":"Animal","details":"A timid elephant and loyal friend to Tarzan and Terk, terrified of germs, water, and nearly everything else.","image":"https://vignette.wikia.nocookie.net/disney/images/5/57/Tantor_Tarzan.jpeg/revision/latest"},{"name":"Kerchak","rarity":"common","id":"kerchak","subtitle":"Animal","details":"The gorilla troop's stern silverback leader, who never fully accepts the human child Kala brings home.","image":"https://vignette.wikia.nocookie.net/disney/images/3/31/Kerchak_Tarzan.jpg/revision/latest"},{"name":"Kala","rarity":"common","id":"kala","subtitle":"Animal","details":"The gentle gorilla mother who rescues the orphaned baby Tarzan and raises him against Kerchak's wishes.","image":"https://vignette.wikia.nocookie.net/disney/images/c/c8/Kala_Tarzan.jpg/revision/latest"},{"name":"Spring Sprite","rarity":"common","id":"spring-sprite","subtitle":"Spirit","details":"The wordless spirit of spring in Fantasia 2000, whose awakening of a forest is nearly ended by the Firebird's eruption.","image":"https://vignette.wikia.nocookie.net/disney/images/6/6a/Profile_-_Spring_Sprite.jpg/revision/latest"},{"name":"Firebird","rarity":"common","id":"firebird","subtitle":"Spirit","details":"The volcanic spirit of Fantasia 2000, whose eruption buries the forest in ash before spring slowly returns.","image":"https://vignette.wikia.nocookie.net/disney/images/a/a7/Fantasia-disneyscreencaps_com-7469.jpg/revision/latest"},{"name":"Aladar","rarity":"common","id":"aladar","subtitle":"Animal","details":"An Iguanodon raised by lemurs who leads a migrating herd of dinosaurs across a desert to the Nesting Grounds.","image":"https://vignette.wikia.nocookie.net/disney/images/e/e2/Profile_-_Aladar.png/revision/latest"},{"name":"Neera","rarity":"common","id":"neera","subtitle":"Animal","details":"A strong-willed Iguanodon of Kron's herd who questions its brutal rules after meeting the gentle Aladar.","image":"https://vignette.wikia.nocookie.net/disney/images/c/c8/Profile_-_Neera.jpg/revision/latest"},{"name":"Kuzco","rarity":"rare","id":"kuzco","subtitle":"King","details":"A selfish Incan emperor turned into a llama by his own adviser, who learns humility on the road back to his throne.","image":"https://vignette.wikia.nocookie.net/disney/images/f/ff/Profile_-_Kuzco.jpeg/revision/latest"},{"name":"Pacha","rarity":"uncommon","id":"pacha","subtitle":"Hero","details":"A kind, sturdy peasant village leader whose family and hilltop home stand in the way of Kuzco's summer palace.","image":"https://vignette.wikia.nocookie.net/disney/images/e/e7/Pacha.jpg/revision/latest"},{"name":"Yzma","rarity":"uncommon","id":"yzma","subtitle":"Villain","details":"Kuzco's ancient, scheming adviser, a potion-mixing villain whose plans always begin with pulling the wrong lever.","image":"https://vignette.wikia.nocookie.net/disney/images/f/f2/Profile_-_Yzma.jpeg/revision/latest"},{"name":"Kronk","rarity":"uncommon","id":"kronk","subtitle":"Sidekick","details":"Yzma's huge, gentle-hearted henchman, a spinach-puff baker who talks to squirrels and hears his shoulder angel.","image":"https://vignette.wikia.nocookie.net/disney/images/6/64/Kronk_.jpg/revision/latest"},{"name":"Chicha","rarity":"common","id":"chicha","subtitle":"Heroine","details":"Pacha's capable, no-nonsense wife, who defends her home and family with a frying pan and a level head.","image":"https://vignette.wikia.nocookie.net/disney/images/e/e3/Chicha.jpg/revision/latest"},{"name":"Bucky the Squirrel","rarity":"common","id":"bucky-the-squirrel","subtitle":"Animal","details":"A chattering squirrel whose squeaked warnings Kronk understands perfectly, and whose bad luck sparks a jaguar chase.","image":"https://vignette.wikia.nocookie.net/disney/images/7/76/Emperors-new-groove-disneyscreencaps.com-3305.jpg/revision/latest"},{"name":"Milo Thatch","rarity":"uncommon","id":"milo-thatch","subtitle":"Hero","details":"A linguist and mapmaker at the Smithsonian who deciphers an ancient journal and leads an expedition to Atlantis.","image":"https://vignette.wikia.nocookie.net/disney/images/4/40/Profile_-_Milo_Thatch.png/revision/latest"},{"name":"Kida","rarity":"rare","id":"kida","subtitle":"Princess","details":"Atlantis's warrior princess, full name Kidagakash Nedakh, who has lived for thousands of years guarding her city.","image":"https://vignette.wikia.nocookie.net/disney/images/3/34/Profile_-_Kida_Nedakh.jpeg/revision/latest"},{"name":"Commander Rourke","rarity":"common","id":"commander-rourke","subtitle":"Villain","details":"The Atlantis expedition's commander, whose soldierly calm hides a plan to steal the city's crystal heart and sell it.","image":"https://vignette.wikia.nocookie.net/disney/images/c/c5/Profile_-_Lyle_Tiberius_Rourke.png/revision/latest"},{"name":"Helga Sinclair","rarity":"common","id":"helga-sinclair","subtitle":"Villain","details":"Rourke's cool, capable second-in-command, a marksman whose loyalty to the mission is tested in Atlantis.","image":"https://vignette.wikia.nocookie.net/disney/images/b/bc/Profile_-_Helga_Sinclair.jpg/revision/latest"},{"name":"Vinny Santorini","rarity":"common","id":"vinny-santorini","subtitle":"Hero","details":"The expedition's laconic Italian demolitions expert, who can solve almost any problem with the right explosion.","image":"https://vignette.wikia.nocookie.net/disney/images/1/1f/Profile_-_Vincenzo_Santorini.png/revision/latest"},{"name":"Audrey Ramirez","rarity":"common","id":"audrey-ramirez","subtitle":"Heroine","details":"The expedition's teenage mechanic, a brilliant engineer who keeps the sub and trucks running on grit alone.","image":"https://vignette.wikia.nocookie.net/disney/images/6/66/Profile_-_Audrey.png/revision/latest"},{"name":"Dr. Joshua Sweet","rarity":"common","id":"dr-joshua-sweet","subtitle":"Hero","details":"The expedition's towering, gentle medic, a fast-talking doctor who treats every injury before you notice it.","image":"https://vignette.wikia.nocookie.net/disney/images/5/56/Profile_-_Joshua_Sweet.png/revision/latest"},{"name":"Stitch","rarity":"legendary","id":"stitch","subtitle":"Alien","details":"Experiment 626, a hyperactive blue alien engineered to destroy, who crash-lands in Hawaii and learns what ohana means.","image":"https://vignette.wikia.nocookie.net/disney/images/b/b7/Profile_-_Stitch.jpg/revision/latest"},{"name":"Lilo Pelekai","rarity":"epic","id":"lilo-pelekai","subtitle":"Heroine","details":"A lonely Hawaiian girl who adopts a 'dog' from the shelter, feeds Pudge the fish, and believes nobody gets left behind.","image":"https://vignette.wikia.nocookie.net/disney/images/1/1f/Profile_-_Lilo.png/revision/latest"},{"name":"Nani Pelekai","rarity":"rare","id":"nani-pelekai","subtitle":"Heroine","details":"Lilo's older sister and guardian, juggling jobs and social workers to keep her little family of two together.","image":"https://vignette.wikia.nocookie.net/disney/images/d/d0/Nani_Pelekai_LAS.jpg/revision/latest"},{"name":"Jumba Jookiba","rarity":"uncommon","id":"jumba-jookiba","subtitle":"Alien","details":"The self-described evil genius who created Stitch in an illegal experiment and is sent to Earth to recapture him.","image":"https://vignette.wikia.nocookie.net/disney/images/3/3d/Profile_-_Jumba.jpg/revision/latest"},{"name":"Pleakley","rarity":"uncommon","id":"pleakley","subtitle":"Alien","details":"A one-eyed, Earth-obsessed Galactic Federation agent partnered with Jumba, fascinated by mosquitoes and wigs.","image":"https://vignette.wikia.nocookie.net/disney/images/4/48/Profile_-_Pleakley.jpg/revision/latest"},{"name":"Captain Gantu","rarity":"common","id":"captain-gantu","subtitle":"Alien","details":"The Galactic Federation's hulking captain, sent to retrieve Stitch and deeply insulted at being called a shark.","image":"https://vignette.wikia.nocookie.net/disney/images/5/50/Profile_-_Captain_Gantu.jpeg/revision/latest"},{"name":"David Kawena","rarity":"common","id":"david-kawena","subtitle":"Hero","details":"Nani's kind, fire-dancing friend, a lifeguard whose patience and surfing outlast every Pelekai family disaster.","image":"https://vignette.wikia.nocookie.net/disney/images/1/11/David_Kawena_LAS.jpg/revision/latest"},{"name":"Jim Hawkins","rarity":"uncommon","id":"jim-hawkins","subtitle":"Hero","details":"A rebellious young solar surfer who finds a map to Treasure Planet and sails the stars aboard the RLS Legacy.","image":"https://vignette.wikia.nocookie.net/disney/images/c/c5/Profile_-_Jim_Hawkins.jpeg/revision/latest"},{"name":"John Silver","rarity":"uncommon","id":"john-silver","subtitle":"Villain","details":"A cyborg cook and secret pirate captain whose fatherly bond with Jim Hawkins conflicts with his hunt for treasure.","image":"https://vignette.wikia.nocookie.net/disney/images/a/ae/Profile_-_John_Silver.jpeg/revision/latest"},{"name":"Captain Amelia","rarity":"common","id":"captain-amelia","subtitle":"Heroine","details":"The feline, razor-sharp captain of the RLS Legacy, all discipline and daring in a starched uniform.","image":"https://vignette.wikia.nocookie.net/disney/images/0/0c/Profile_-_Captain_Amelia.png/revision/latest"},{"name":"Dr. Delbert Doppler","rarity":"common","id":"dr-delbert-doppler","subtitle":"Sidekick","details":"A dog-like astrophysicist who funds the Treasure Planet voyage and bumbles his way into Captain Amelia's heart.","image":"https://vignette.wikia.nocookie.net/disney/images/7/72/Profile_-_Dr._Doppler.jpeg/revision/latest"},{"name":"B.E.N.","rarity":"common","id":"ben","subtitle":"Robot","details":"B.E.N., a marooned navigation robot left on Treasure Planet for a century, missing his memory chip and his mind.","image":"https://vignette.wikia.nocookie.net/disney/images/1/18/Profile_-_B.E.N..png/revision/latest"},{"name":"Morph","rarity":"common","id":"morph","subtitle":"Alien","details":"Silver's shape-shifting pink pet, a floating blob who mimics anything and adores Jim Hawkins on sight.","image":"https://vignette.wikia.nocookie.net/disney/images/6/6e/Treasure-planet-disneyscreencaps.com-2618.jpg/revision/latest"},{"name":"Kenai","rarity":"uncommon","id":"kenai","subtitle":"Hero","details":"A young hunter transformed into a bear by the spirits to learn empathy after killing Koda's mother in anger.","image":"https://vignette.wikia.nocookie.net/disney/images/a/a0/Profile_-_Kenai.jpeg/revision/latest"},{"name":"Koda","rarity":"uncommon","id":"koda","subtitle":"Animal","details":"A talkative bear cub who guides Kenai to the mountain of lights while cheerfully retelling the salmon run.","image":"https://vignette.wikia.nocookie.net/disney/images/1/10/Koda.jpg/revision/latest"},{"name":"Rutt","rarity":"common","id":"rutt","subtitle":"Animal","details":"One of two dim, good-natured Canadian moose whose philosophical rambling bewilders every bear they meet.","image":"https://vignette.wikia.nocookie.net/disney/images/5/5c/Brother-bear-disneyscreencaps.com-3299.jpg/revision/latest"},{"name":"Tuke","rarity":"common","id":"tuke","subtitle":"Animal","details":"The other half of the moose duo, Rutt's brother in antlers and in cheerful, meandering conversation.","image":"https://vignette.wikia.nocookie.net/disney/images/5/5c/Brother-bear-disneyscreencaps.com-3299.jpg/revision/latest"},{"name":"Denahi","rarity":"common","id":"denahi","subtitle":"Villain","details":"Kenai's middle brother, who believes a bear killed Kenai and hunts it across the mountains for revenge.","image":"https://vignette.wikia.nocookie.net/disney/images/b/bf/Brother-bear-disneyscreencaps.com-1056.jpg/revision/latest"},{"name":"Maggie","rarity":"common","id":"maggie","subtitle":"Animal","details":"A wisecracking show cow who rallies her fellow farm animals to capture a cattle rustler and save their farm.","image":"https://vignette.wikia.nocookie.net/disney/images/f/f5/Profile_-_Maggie.jpg/revision/latest"},{"name":"Mrs. Calloway","rarity":"common","id":"mrs-calloway","subtitle":"Animal","details":"The Patch of Heaven farm's prim, proper lead cow, whose dignity survives even Maggie's constant teasing.","image":"https://vignette.wikia.nocookie.net/disney/images/8/8c/Profile_-_Mrs._Calloway.jpg/revision/latest"},{"name":"Chicken Little","rarity":"uncommon","id":"chicken-little","subtitle":"Hero","details":"A tiny chicken whose cry that the sky is falling makes him a town joke - until the sky obligingly falls again.","image":"https://vignette.wikia.nocookie.net/disney/images/2/28/Profile_-_Chicken_Little.jpeg/revision/latest"},{"name":"Abby Mallard","rarity":"common","id":"abby-mallard","subtitle":"Heroine","details":"Chicken Little's supportive duck friend, an 'ugly duckling' with a crush, a clipboard, and endless encouragement.","image":"https://vignette.wikia.nocookie.net/disney/images/f/f1/Profile_-_Abby_Mallard.jpeg/revision/latest"},{"name":"Runt of the Litter","rarity":"common","id":"runt-of-the-litter","subtitle":"Animal","details":"A huge, gentle pig and Chicken Little's friend, whose size never matches his timid, soft-spoken nature.","image":"https://vignette.wikia.nocookie.net/disney/images/b/b4/Profile-_Runt_of_the_Litter.jpg/revision/latest"},{"name":"Fish Out of Water","rarity":"common","id":"fish-out-of-water","subtitle":"Animal","details":"Chicken Little's silent goldfish friend, who travels in a water-filled helmet and communicates in pure mime.","image":"https://vignette.wikia.nocookie.net/disney/images/0/07/Profile_-_Fish_Out_of_Water.jpg/revision/latest"},{"name":"Lewis Robinson","rarity":"uncommon","id":"lewis-robinson","subtitle":"Hero","details":"A young orphan inventor whose memory scanner draws a time-traveling boy - and a bowler-hatted thief - into his life.","image":"https://vignette.wikia.nocookie.net/disney/images/d/dd/Profile_-_Lewis_Robinson.jpeg/revision/latest"},{"name":"Wilbur Robinson","rarity":"common","id":"wilbur-robinson","subtitle":"Hero","details":"A time-traveling teenager who whisks Lewis to the future, mostly to hide a mistake involving the time machines.","image":"https://vignette.wikia.nocookie.net/disney/images/0/04/Profile_-_Wilbur_Robinson.jpg/revision/latest"},{"name":"Bowler Hat Guy","rarity":"common","id":"bowler-hat-guy","subtitle":"Villain","details":"A lanky, bitter villain in a bowler hat, aided by the robotic hat Doris in a plot against the Robinson family.","image":"https://vignette.wikia.nocookie.net/disney/images/8/8e/Profile_-_Bowler_Hat_Guy.jpg/revision/latest"},{"name":"Franny Robinson","rarity":"common","id":"franny-robinson","subtitle":"Heroine","details":"Wilbur's mother in the future, who trains singing frogs and believes music belongs absolutely everywhere.","image":"https://vignette.wikia.nocookie.net/disney/images/2/20/New_Franny_Header.jpg/revision/latest"},{"name":"Bolt","rarity":"uncommon","id":"bolt","subtitle":"Animal","details":"A white shepherd TV star who believes his superpowers are real and crosses America to rescue his person, Penny.","image":"https://vignette.wikia.nocookie.net/disney/images/2/29/Profile_-_Bolt.jpeg/revision/latest"},{"name":"Mittens","rarity":"uncommon","id":"mittens","subtitle":"Animal","details":"A declawed, streetwise New York alley cat dragged along on Bolt's journey, slowly teaching him how to be a dog.","image":"https://vignette.wikia.nocookie.net/disney/images/c/cb/Profile_-_Mittens.jpg/revision/latest"},{"name":"Rhino","rarity":"common","id":"rhino","subtitle":"Animal","details":"Bolt's hamster superfan in a plastic ball, whose absolute faith in the TV hero carries the trio through danger.","image":"https://vignette.wikia.nocookie.net/disney/images/4/4d/Profile_-_Rhino.jpg/revision/latest"},{"name":"Penny Forrester","rarity":"common","id":"penny-forrester","subtitle":"Heroine","details":"Bolt's young co-star and owner, who plays Penny on TV and simply wants her lost dog home in real life too.","image":"https://vignette.wikia.nocookie.net/disney/images/8/81/Profile_-_Penny_%28Bolt%29.png/revision/latest"},{"name":"Tiana","rarity":"epic","id":"tiana","subtitle":"Princess","details":"A hardworking New Orleans waitress of 2009 saving for her own restaurant, whose kiss on a frog prince backfires.","image":"https://vignette.wikia.nocookie.net/disney/images/f/fa/Profile_-_Tiana.jpeg/revision/latest"},{"name":"Prince Naveen","rarity":"rare","id":"prince-naveen","subtitle":"Prince","details":"A charming, penniless Maldonian prince turned frog by Dr. Facilier, whose idleness Tiana's work ethic challenges.","image":"https://vignette.wikia.nocookie.net/disney/images/9/92/Profile_-_Prince_Naveen.jpeg/revision/latest"},{"name":"Charlotte La Bouff","rarity":"uncommon","id":"charlotte-la-bouff","subtitle":"Sidekick","details":"Tiana's exuberant, fairy-tale-obsessed best friend, a wealthy belle who dreams of marrying a prince of her own.","image":"https://vignette.wikia.nocookie.net/disney/images/0/0e/Charlotte_La_Bouff.jpeg/revision/latest"},{"name":"Dr. Facilier","rarity":"uncommon","id":"dr-facilier","subtitle":"Villain","details":"The Shadow Man, a New Orleans bokor whose friends on the other side turn Prince Naveen into a frog.","image":"https://vignette.wikia.nocookie.net/disney/images/3/3f/Profile_-_Dr._Facilier.jpeg/revision/latest"},{"name":"Louis","rarity":"uncommon","id":"louis","subtitle":"Animal","details":"A huge, gentle alligator who dreams of playing jazz trumpet with the greats and joins the frogs' bayou journey.","image":"https://vignette.wikia.nocookie.net/disney/images/e/e4/Profile_-_Louis_the_alligator.jpeg/revision/latest"},{"name":"Ray","rarity":"uncommon","id":"ray","subtitle":"Animal","details":"A lovesick Cajun firefly whose devotion to his star 'Evangeline' lights the bayou frogs' darkest night.","image":"https://vignette.wikia.nocookie.net/disney/images/3/37/Profile_-_Ray.jpeg/revision/latest"},{"name":"Mama Odie","rarity":"common","id":"mama-odie","subtitle":"Sorcerer","details":"A blind, 197-year-old voodoo priestess of the bayou who tells Tiana to dig a little deeper for what she needs.","image":"https://vignette.wikia.nocookie.net/disney/images/3/35/Profile_-_Mama_Odie.jpeg/revision/latest"},{"name":"Lawrence","rarity":"common","id":"lawrence","subtitle":"Villain","details":"Naveen's put-upon valet, transformed by Facilier's magic into a prince-shaped impostor for a New Orleans wedding.","image":"https://vignette.wikia.nocookie.net/disney/images/6/6a/Profile_-_Lawrence.jpeg/revision/latest"},{"name":"Eli La Bouff","rarity":"common","id":"eli-la-bouff","subtitle":"Hero","details":"Charlotte's doting father, 'Big Daddy' La Bouff, a sugar baron who would buy his daughter anything but sense.","image":"https://vignette.wikia.nocookie.net/disney/images/c/c3/Profile_-_Eli_Big_Daddy_La_Bouff.jpeg/revision/latest"},{"name":"Rapunzel","rarity":"legendary","id":"rapunzel","subtitle":"Princess","details":"A princess with seventy feet of magical, golden hair, locked in a tower for eighteen years by Mother Gothel.","image":"https://vignette.wikia.nocookie.net/disney/images/a/ae/Profile_-_Rapunzel.jpeg/revision/latest"},{"name":"Flynn Rider","rarity":"rare","id":"flynn-rider","subtitle":"Hero","details":"A dashing thief, real name Eugene Fitzherbert, hired by Rapunzel to guide her to the floating lanterns.","image":"https://vignette.wikia.nocookie.net/disney/images/8/84/Profile_-_Flynn_Rider.jpeg/revision/latest"},{"name":"Mother Gothel","rarity":"rare","id":"mother-gothel","subtitle":"Villain","details":"The vain woman who stole baby Rapunzel for her hair's youth-giving magic and posed as her loving mother.","image":"https://vignette.wikia.nocookie.net/disney/images/f/f9/Profile_-_Mother_Gothel.jpeg/revision/latest"},{"name":"Pascal","rarity":"uncommon","id":"pascal","subtitle":"Animal","details":"Rapunzel's silent chameleon companion, a color-changing little guardian with strong opinions about Flynn Rider.","image":"https://vignette.wikia.nocookie.net/disney/images/b/ba/Profile_-_Pascal.png/revision/latest"},{"name":"Maximus","rarity":"uncommon","id":"maximus","subtitle":"Animal","details":"A determined palace horse who hunts Flynn Rider like a bloodhound and enforces the law with a sword in his teeth.","image":"https://vignette.wikia.nocookie.net/disney/images/7/7a/Profile_-_Maximus.jpeg/revision/latest"},{"name":"King Frederic","rarity":"common","id":"king-frederic","subtitle":"King","details":"Rapunzel's father, Corona's king, whose grief over his stolen daughter fills the sky with lanterns each year.","image":"https://vignette.wikia.nocookie.net/disney/images/5/57/King_of_Corona_Tangled_.jpg/revision/latest"},{"name":"Queen Arianna","rarity":"common","id":"queen-arianna","subtitle":"Queen","details":"Rapunzel's mother, Corona's gentle queen, saved before her daughter's birth by a magical golden flower.","image":"https://vignette.wikia.nocookie.net/disney/images/1/15/Arianna_Tangled.jpg/revision/latest"},{"name":"Stabbington Brothers","rarity":"common","id":"stabbington-brothers","subtitle":"Villain","details":"A pair of hulking, silent thugs betrayed by Flynn Rider who pursue him and Rapunzel across the kingdom.","image":"https://vignette.wikia.nocookie.net/disney/images/a/a2/Stabbingtons.jpg/revision/latest"},{"name":"Wreck-It Ralph","rarity":"rare","id":"wreck-it-ralph","subtitle":"Hero","details":"The gentle giant villain of Fix-It Felix Jr., who leaves his game in 2012 tired of being treated as a bad guy.","image":"https://vignette.wikia.nocookie.net/disney/images/d/da/Wreck_it_Ralph_pose_transparent.png/revision/latest"},{"name":"Vanellope von Schweetz","rarity":"rare","id":"vanellope-von-schweetz","subtitle":"Princess","details":"A glitchy young racer from Sugar Rush who dreams of racing for real and becomes Ralph's first true friend.","image":"https://vignette.wikia.nocookie.net/disney/images/2/25/Profile_-_Vanellope_Von_schweetz.jpeg/revision/latest"},{"name":"Fix-It Felix Jr.","rarity":"uncommon","id":"fix-it-felix-jr","subtitle":"Hero","details":"The golden-hammered hero of his own arcade game, whose niceness is legendary in Niceland and beyond.","image":"https://vignette.wikia.nocookie.net/disney/images/a/a6/Profile_-_Fix_It_Felix_Jr.jpeg/revision/latest"},{"name":"Sergeant Calhoun","rarity":"uncommon","id":"sergeant-calhoun","subtitle":"Heroine","details":"The hard-as-nails commander of Hero's Duty, programmed with a tragic backstory and zero tolerance for nonsense.","image":"https://vignette.wikia.nocookie.net/disney/images/b/b5/Profile_-_Sergeant_Calhoun.jpeg/revision/latest"},{"name":"King Candy","rarity":"uncommon","id":"king-candy","subtitle":"Villain","details":"Sugar Rush's lisping, flamboyant ruler, secretly the exiled racer Turbo hiding behind a stolen kingdom and code.","image":"https://vignette.wikia.nocookie.net/disney/images/e/ee/Profile_-_King_Candy.jpeg/revision/latest"},{"name":"Taffyta Muttonfudge","rarity":"common","id":"taffyta-muttonfudge","subtitle":"Villain","details":"Sugar Rush's mean-girl lead racer, who leads the bullying of Vanellope before learning who she really is.","image":"https://vignette.wikia.nocookie.net/disney/images/3/3b/Profile_-_Taffyta_Muttonfudge.jpeg/revision/latest"},{"name":"Sour Bill","rarity":"common","id":"sour-bill","subtitle":"Sidekick","details":"King Candy's glum, monotone candy henchman, a small green sour ball with nothing cheerful to report.","image":"https://vignette.wikia.nocookie.net/disney/images/f/f0/Profile_-_Sour_Bill.jpeg/revision/latest"},{"name":"Shank","rarity":"common","id":"shank","subtitle":"Heroine","details":"The cool, skilled star driver of the online racing game Slaughter Race, who becomes Vanellope's mentor on the internet.","image":"https://vignette.wikia.nocookie.net/disney/images/6/67/Profile_-_Shank.png/revision/latest"},{"name":"Elsa","rarity":"chase","id":"elsa","subtitle":"Queen","details":"Arendelle's Snow Queen, born with ice magic she hid for years until 'Let It Go' set her - and her kingdom's winter - free.","image":"https://vignette.wikia.nocookie.net/disney/images/9/95/Profile_-_Elsa.jpeg/revision/latest"},{"name":"Anna","rarity":"legendary","id":"anna","subtitle":"Princess","details":"Elsa's fearless younger sister, whose act of true love - saving her sister instead of herself - thaws a frozen heart.","image":"https://vignette.wikia.nocookie.net/disney/images/0/0f/Profile_-_Anna.jpeg/revision/latest"},{"name":"Olaf","rarity":"legendary","id":"olaf","subtitle":"Sidekick","details":"A cheerful snowman built by Elsa and Anna as children, who loves warm hugs and dreams innocently of summer.","image":"https://vignette.wikia.nocookie.net/disney/images/5/53/Profile_-_Olaf.jpeg/revision/latest"},{"name":"Kristoff","rarity":"epic","id":"kristoff","subtitle":"Hero","details":"A rugged ice harvester raised by trolls, whose blunt honesty and love for Anna outlast every Arendelle disaster.","image":"https://vignette.wikia.nocookie.net/disney/images/b/b4/Profile_-_Kristoff.jpeg/revision/latest"},{"name":"Sven","rarity":"uncommon","id":"sven","subtitle":"Animal","details":"Kristoff's loyal reindeer, best friend, and sled-puller, whose thoughts Kristoff happily voices for him.","image":"https://vignette.wikia.nocookie.net/disney/images/0/0b/Profile_-_Sven.jpeg/revision/latest"},{"name":"Prince Hans","rarity":"uncommon","id":"prince-hans","subtitle":"Prince","details":"The thirteenth prince of the Southern Isles, whose perfect fiance act hides a plan to seize Arendelle's throne.","image":"https://vignette.wikia.nocookie.net/disney/images/e/ee/Profile_-_Hans.jpeg/revision/latest"},{"name":"Marshmallow","rarity":"common","id":"marshmallow","subtitle":"Sidekick","details":"Elsa's hulking snow golem guardian, built to throw Anna and Kristoff off her ice palace steps - crown and all.","image":"https://vignette.wikia.nocookie.net/disney/images/e/e0/Profile_-_Marshmallow.jpeg/revision/latest"},{"name":"Bruni","rarity":"uncommon","id":"bruni","subtitle":"Spirit","details":"The Enchanted Forest's adorable fire spirit, a little blue salamander whose flames Elsa calms with snowflakes.","image":"https://vignette.wikia.nocookie.net/disney/images/3/39/Profile_-_Bruni.jpeg/revision/latest"},{"name":"Nokk","rarity":"common","id":"nokk","subtitle":"Spirit","details":"The Enchanted Forest's water spirit, a wild horse of the Dark Sea that Elsa must tame before it will carry her.","image":"https://vignette.wikia.nocookie.net/disney/images/e/ee/The_Nokk.png/revision/latest"},{"name":"Honeymaren","rarity":"common","id":"honeymaren","subtitle":"Heroine","details":"A Northuldra reindeer herder who befriends Anna and Elsa and helps them uncover Arendelle's buried past.","image":"https://vignette.wikia.nocookie.net/disney/images/a/a5/Profile_-_Honeymaren.jpeg/revision/latest"},{"name":"Lieutenant Mattias","rarity":"common","id":"lieutenant-mattias","subtitle":"Hero","details":"An Arendelle guard lieutenant trapped in the Enchanted Forest for decades, loyal to a kingdom he cannot reach.","image":"https://vignette.wikia.nocookie.net/disney/images/0/0d/Profile_-_Lieutenant_Mattias.jpeg/revision/latest"},{"name":"Baymax","rarity":"epic","id":"baymax","subtitle":"Robot","details":"A soft, inflatable healthcare robot activated by the word 'ow' and programmed to care for Hiro no matter what.","image":"https://vignette.wikia.nocookie.net/disney/images/d/d4/Profile_-_Baymax.jpeg/revision/latest"},{"name":"Hiro Hamada","rarity":"rare","id":"hiro-hamada","subtitle":"Hero","details":"A teenage robotics prodigy of San Fransokyo who turns his brother's healthcare robot into a superhero teammate.","image":"https://vignette.wikia.nocookie.net/disney/images/2/21/Profile_-_Hiro_Hamada.jpeg/revision/latest"},{"name":"Tadashi Hamada","rarity":"common","id":"tadashi-hamada","subtitle":"Hero","details":"Hiro's selfless older brother, creator of Baymax, whose kindness shapes every hero his brother becomes.","image":"https://vignette.wikia.nocookie.net/disney/images/1/1f/Tadashi_Hamada.jpeg/revision/latest"},{"name":"Go Go Tomago","rarity":"uncommon","id":"go-go-tomago","subtitle":"Heroine","details":"A no-nonsense engineering student whose electromagnetic bike discs become the fastest wheels on the Big Hero 6.","image":"https://vignette.wikia.nocookie.net/disney/images/9/95/Profile_-_GoGo_Tomago.png/revision/latest"},{"name":"Wasabi","rarity":"uncommon","id":"wasabi","subtitle":"Hero","details":"A meticulous applied-physics student whose laser-induced plasma blades are as precise as his organisation.","image":"https://vignette.wikia.nocookie.net/disney/images/3/30/Profile_-_Wasabi.jpeg/revision/latest"},{"name":"Honey Lemon","rarity":"uncommon","id":"honey-lemon","subtitle":"Heroine","details":"A bubbly chemistry whiz whose purse of chemical mixtures freezes, sticks, or explodes exactly as programmed.","image":"https://vignette.wikia.nocookie.net/disney/images/8/89/Profile_-_Honey_Lemon.jpeg/revision/latest"},{"name":"Fred","rarity":"uncommon","id":"fred","subtitle":"Hero","details":"A comic-book superfan and college mascot whose kaiju costume breathes fire and fulfills his wildest fan dreams.","image":"https://vignette.wikia.nocookie.net/disney/images/f/f9/Profile_-_Fred.png/revision/latest"},{"name":"Robert Callaghan","rarity":"common","id":"robert-callaghan","subtitle":"Villain","details":"San Fransokyo's respected robotics professor, secretly the masked Yokai behind a stolen microbot swarm.","image":"https://vignette.wikia.nocookie.net/disney/images/0/00/Yokai_Big_Hero_6_Profile.jpg/revision/latest"},{"name":"Judy Hopps","rarity":"epic","id":"judy-hopps","subtitle":"Heroine","details":"The first rabbit police officer in Zootopia, a determined optimist from Bunnyburrow who refuses to quit a case.","image":"https://vignette.wikia.nocookie.net/disney/images/d/da/Profile_-_Judy_Hopps.jpeg/revision/latest"},{"name":"Nick Wilde","rarity":"epic","id":"nick-wilde","subtitle":"Hero","details":"A sly fox con artist whose pawpsicle hustle Judy recruits - and whose past explains his distrust of trying.","image":"https://vignette.wikia.nocookie.net/disney/images/5/50/Profile_-_Nick_Wilde.jpeg/revision/latest"},{"name":"Chief Bogo","rarity":"uncommon","id":"chief-bogo","subtitle":"Animal","details":"Zootopia's stern cape buffalo police chief, who assigns Officer Hopps to parking duty and doubts her openly.","image":"https://vignette.wikia.nocookie.net/disney/images/6/63/Profile_-_Chief_Bogo.jpeg/revision/latest"},{"name":"Dawn Bellwether","rarity":"uncommon","id":"dawn-bellwether","subtitle":"Villain","details":"Mayor Lionheart's meek sheep assistant, whose smile hides a plot to turn predators and prey against each other.","image":"https://vignette.wikia.nocookie.net/disney/images/8/85/Profile_-_Bellwether_.jpeg/revision/latest"},{"name":"Benjamin Clawhauser","rarity":"uncommon","id":"benjamin-clawhauser","subtitle":"Animal","details":"The ZPD's donut-loving cheetah desk officer, whose cheerful gossip greets everyone entering headquarters.","image":"https://vignette.wikia.nocookie.net/disney/images/7/7b/Profile_-_Clawhauser.jpeg/revision/latest"},{"name":"Gazelle","rarity":"common","id":"gazelle","subtitle":"Animal","details":"Zootopia's biggest pop star, a gazelle voiced by Shakira whose song 'Try Everything' is the city's anthem.","image":"https://vignette.wikia.nocookie.net/disney/images/9/9a/Profile_-_Gazelle.jpeg/revision/latest"},{"name":"Flash Slothmore","rarity":"common","id":"flash-slothmore","subtitle":"Animal","details":"The DMV's fastest sloth, whose agonizingly slow service nearly breaks Judy and Nick's entire investigation.","image":"https://vignette.wikia.nocookie.net/disney/images/8/8e/Profile_-_Flash.jpg/revision/latest"},{"name":"Mr. Big","rarity":"common","id":"mr-big","subtitle":"Animal","details":"Tundratown's tiny arctic shrew crime boss, whose threats to 'ice' his enemies vastly outweigh his size.","image":"https://vignette.wikia.nocookie.net/disney/images/8/85/Profile_-_Mr._Big.jpeg/revision/latest"},{"name":"Duke Weaselton","rarity":"common","id":"duke-weaselton","subtitle":"Animal","details":"A small-time weasel crook whose bootleg movies and stolen flower bulbs crack Judy and Nick's biggest case.","image":"https://vignette.wikia.nocookie.net/disney/images/7/77/Duke_Weaselton.jpg/revision/latest"},{"name":"Moana","rarity":"legendary","id":"moana","subtitle":"Heroine","details":"A wayfinding chief's daughter of Motunui who sails beyond the reef in 2016 to return the heart of Te Fiti.","image":"https://vignette.wikia.nocookie.net/disney/images/7/7d/Profile_-_Moana.png/revision/latest"},{"name":"Maui","rarity":"legendary","id":"maui","subtitle":"Hero","details":"The boastful demigod of the wind and sea, whose stolen heart doomed the islands and whose hook Moana restores.","image":"https://vignette.wikia.nocookie.net/disney/images/6/6f/Profile_-_Maui.jpeg/revision/latest"},{"name":"Pua","rarity":"common","id":"pua","subtitle":"Animal","details":"Moana's loyal little pig, an adorable shore-side companion who stays behind when her voyage truly begins.","image":"https://vignette.wikia.nocookie.net/disney/images/9/97/Profile_-_Pua.jpeg/revision/latest"},{"name":"Heihei","rarity":"uncommon","id":"heihei","subtitle":"Animal","details":"A remarkably dim rooster who stows away on Moana's canoe and survives the entire voyage by sheer accident.","image":"https://vignette.wikia.nocookie.net/disney/images/6/6b/Profile_-_Heihei.jpeg/revision/latest"},{"name":"Chief Tui","rarity":"common","id":"chief-tui","subtitle":"King","details":"Motunui's protective chief and Moana's father, whose own lost friend taught him to fear the sea beyond the reef.","image":"https://vignette.wikia.nocookie.net/disney/images/1/1d/Profile_%E2%80%94_Chief_Tui.jpeg/revision/latest"},{"name":"Sina","rarity":"common","id":"sina","subtitle":"Heroine","details":"Moana's wise, supportive mother, who understands her daughter's pull toward the ocean better than Tui does.","image":"https://vignette.wikia.nocookie.net/disney/images/2/2f/Sina_Moana.jpg/revision/latest"},{"name":"Gramma Tala","rarity":"uncommon","id":"gramma-tala","subtitle":"Sidekick","details":"Motunui's self-described crazy village elder, whose stories, dancing waters, and manta ray spirit guide Moana.","image":"https://vignette.wikia.nocookie.net/disney/images/e/e5/Profile_-_Gramma_Tala.jpeg/revision/latest"},{"name":"Tamatoa","rarity":"uncommon","id":"tamatoa","subtitle":"Villain","details":"A giant, treasure-hoarding coconut crab in the realm of monsters, still shiny and still nursing a Maui grudge.","image":"https://vignette.wikia.nocookie.net/disney/images/c/c5/Profile_-_Tamatoa.jpeg/revision/latest"},{"name":"Te Fiti","rarity":"common","id":"te-fiti","subtitle":"Spirit","details":"The island goddess of life whose stolen heart became the lava demon Te Ka until Moana restored it in 2016.","image":"https://vignette.wikia.nocookie.net/disney/images/b/b2/Te_Fiti_%28Profile%29.png/revision/latest"},{"name":"Matangi","rarity":"common","id":"matangi","subtitle":"Villain","details":"A mysterious bat goddess of the underworld in Moana 2 (2024), whose riddles guard a path to a lost island.","image":"https://vignette.wikia.nocookie.net/disney/images/0/09/Profile_-_Matangi.png/revision/latest"},{"name":"Raya","rarity":"uncommon","id":"raya","subtitle":"Princess","details":"Kumandra's lone warrior princess, searching for the last dragon to undo the Druun and reunite her broken land.","image":"https://vignette.wikia.nocookie.net/disney/images/8/8b/Profile_-_Raya.jpg/revision/latest"},{"name":"Sisu","rarity":"uncommon","id":"sisu","subtitle":"Animal","details":"The last dragon of Kumandra, a goofy, trusting water dragon who believes the world's pieces fit back together.","image":"https://vignette.wikia.nocookie.net/disney/images/2/20/Profile_-_Sisu.jpeg/revision/latest"},{"name":"Namaari","rarity":"uncommon","id":"namaari","subtitle":"Villain","details":"Fang's warrior princess, whose childhood betrayal of Raya began a rivalry that ends in an act of trust.","image":"https://vignette.wikia.nocookie.net/disney/images/9/9a/Profile_-_Namaari.png/revision/latest"},{"name":"Boun","rarity":"common","id":"boun","subtitle":"Sidekick","details":"A ten-year-old shrimp-boat captain and chef of Tail, whose business hustle hides a family lost to the Druun.","image":"https://vignette.wikia.nocookie.net/disney/images/b/b9/Profile_-_Boun.jpeg/revision/latest"},{"name":"Noi","rarity":"common","id":"noi","subtitle":"Sidekick","details":"A thieving toddler of Talon whose con-baby act, with her Ongi helpers, robs travelers before Raya recruits her.","image":"https://vignette.wikia.nocookie.net/disney/images/6/68/Profile_-_Noi.jpeg/revision/latest"},{"name":"Tong","rarity":"common","id":"tong","subtitle":"Hero","details":"A giant, gentle warrior of Spine, the last of his people, whose fierce exterior hides a grieving father's heart.","image":"https://vignette.wikia.nocookie.net/disney/images/0/09/Profile_-_Tong.jpeg/revision/latest"},{"name":"Chief Benja","rarity":"common","id":"chief-benja","subtitle":"King","details":"Raya's wise father, Chief of Heart, whose dream of a united Kumandra begins with a fateful feast of all lands.","image":"https://vignette.wikia.nocookie.net/disney/images/f/fc/Profile_-_Chief_Benja.jpeg/revision/latest"},{"name":"Mirabel Madrigal","rarity":"epic","id":"mirabel-madrigal","subtitle":"Heroine","details":"The only ordinary child of a magical Colombian family, whose love for her home saves its miracle in 2021.","image":"https://vignette.wikia.nocookie.net/disney/images/2/2e/Profile_-_Mirabel_Madrigal.png/revision/latest"},{"name":"Bruno Madrigal","rarity":"epic","id":"bruno-madrigal","subtitle":"Hero","details":"The Madrigals' lost uncle, a seer hidden in the walls for ten years - and yes, everyone talks about Bruno.","image":"https://vignette.wikia.nocookie.net/disney/images/3/33/Profile_-_Bruno_Madrigal.png/revision/latest"},{"name":"Isabela Madrigal","rarity":"rare","id":"isabela-madrigal","subtitle":"Heroine","details":"The golden child's perfect eldest sister, whose gift grows flowers - and who longs to grow something wilder.","image":"https://vignette.wikia.nocookie.net/disney/images/4/47/Profile_-_Isabela_Madrigal.png/revision/latest"},{"name":"Luisa Madrigal","rarity":"rare","id":"luisa-madrigal","subtitle":"Heroine","details":"The family's super-strong middle sister, carrying churches, donkeys, and every burden no one thinks to share.","image":"https://vignette.wikia.nocookie.net/disney/images/d/df/Profile_-_Luisa_Madrigal.jpg/revision/latest"},{"name":"Alma Madrigal","rarity":"uncommon","id":"alma-madrigal","subtitle":"Queen","details":"The Madrigal matriarch, Abuela Alma, whose candle miracle built the Casita after she lost her husband Pedro.","image":"https://vignette.wikia.nocookie.net/disney/images/c/c5/Profile_-_Alma_Madrigal.jpg/revision/latest"},{"name":"Dolores Madrigal","rarity":"uncommon","id":"dolores-madrigal","subtitle":"Heroine","details":"The cousin who hears everything in the valley, from a pin drop to Bruno's rats telenovela-ing in the walls.","image":"https://vignette.wikia.nocookie.net/disney/images/c/cf/Profile_-_Dolores_Madrigal.png/revision/latest"},{"name":"Camilo Madrigal","rarity":"uncommon","id":"camilo-madrigal","subtitle":"Hero","details":"The shape-shifting cousin who becomes whoever the moment needs, preferably someone taller and funnier.","image":"https://vignette.wikia.nocookie.net/disney/images/b/bf/Profile_-_Camilo_Madrigal.jpg/revision/latest"},{"name":"Antonio Madrigal","rarity":"uncommon","id":"antonio-madrigal","subtitle":"Hero","details":"The youngest Madrigal, whose gift lets him talk with animals and fills his room with a living jungle.","image":"https://vignette.wikia.nocookie.net/disney/images/2/2e/Antonio_Madrigal.jpg/revision/latest"},{"name":"Pepa Madrigal","rarity":"common","id":"pepa-madrigal","subtitle":"Heroine","details":"The aunt whose moods make the weather - a cloud, a rainbow, or a hurricane over her own wedding day.","image":"https://vignette.wikia.nocookie.net/disney/images/d/d0/Pepa_Madrigal.jpg/revision/latest"},{"name":"Felix Madrigal","rarity":"common","id":"felix-madrigal","subtitle":"Hero","details":"Pepa's fun-loving husband, forever talking his weather-making wife down from a cloud with warmth and rhythm.","image":"https://vignette.wikia.nocookie.net/disney/images/9/90/Profile_-_F%C3%A9lix_Madrigal.png/revision/latest"},{"name":"Julieta Madrigal","rarity":"common","id":"julieta-madrigal","subtitle":"Heroine","details":"Mirabel's mother, whose cooking heals everything from broken hands to bee stings with a single arepa.","image":"https://vignette.wikia.nocookie.net/disney/images/b/ba/Julieta_Madrigal.jpg/revision/latest"},{"name":"Agustin Madrigal","rarity":"common","id":"agustin-madrigal","subtitle":"Hero","details":"Mirabel's accident-prone father, a well-meaning outsider to the magic who attracts bees and falling pianos.","image":"https://vignette.wikia.nocookie.net/disney/images/8/8e/Profile_-_Agust%C3%ADn_Madrigal.jpg/revision/latest"},{"name":"Searcher Clade","rarity":"common","id":"searcher-clade","subtitle":"Hero","details":"A farmer-explorer of Avalonia who grows the miracle plant Pando and dreads following his father's legend.","image":"https://vignette.wikia.nocookie.net/disney/images/6/60/Profile_-_Searcher_Clade.png/revision/latest"},{"name":"Ethan Clade","rarity":"common","id":"ethan-clade","subtitle":"Hero","details":"Searcher's adventurous teenage son, who sneaks aboard the Venture to see the world below his father's farm.","image":"https://vignette.wikia.nocookie.net/disney/images/e/e2/Profile_-_Ethan_Clade.png/revision/latest"},{"name":"Jaeger Clade","rarity":"common","id":"jaeger-clade","subtitle":"Hero","details":"The legendary, larger-than-life explorer father Searcher never stopped measuring himself against.","image":"https://vignette.wikia.nocookie.net/disney/images/1/14/Profile_-_Jaeger_Clade.jpg/revision/latest"},{"name":"Asha","rarity":"uncommon","id":"asha","subtitle":"Heroine","details":"A seventeen-year-old of Rosas who discovers her king hoards his people's wishes and dares to wish upon a star.","image":"https://vignette.wikia.nocookie.net/disney/images/4/40/Profile_-_Asha.jpg/revision/latest"},{"name":"King Magnifico","rarity":"uncommon","id":"king-magnifico","subtitle":"King","details":"Rosas's sorcerer king, who grants only the wishes that suit him and keeps the rest glowing in his study.","image":"https://vignette.wikia.nocookie.net/disney/images/b/b5/Profile_-_King_Magnifico.jpg/revision/latest"},{"name":"Valentino","rarity":"common","id":"valentino","subtitle":"Animal","details":"Asha's loyal pet goat, whose wish grants him a dapper sweater, a deep voice, and endless confident commentary.","image":"https://vignette.wikia.nocookie.net/disney/images/0/0b/Valentino.jpg/revision/latest"},{"name":"Star","rarity":"uncommon","id":"star","subtitle":"Spirit","details":"A small, silent ball of starlight who falls to Rosas answering Asha's wish and turns the kingdom upside down.","image":"https://vignette.wikia.nocookie.net/disney/images/e/ea/Profile_-_Star.png/revision/latest"},{"name":"Queen Amaya","rarity":"common","id":"queen-amaya","subtitle":"Queen","details":"Magnifico's queen, whose quiet conscience leads her to help Asha free the wishes her husband refuses to grant.","image":"https://vignette.wikia.nocookie.net/disney/images/0/0d/Profile_-_Queen_Amaya.png/revision/latest"}]});
